		response := handleMCPMessage(ctx, opts, msg)
		if err := writeMCPMessage(out, response, frameMode); err != nil {
			mcpDebugLog(debugLog, "write_error: "+err.Error())
			return err
		}
		mcpDebugLog(debugLog, "response: "+msg.Method)
	}
}

