// brainBriefIndexedHistoryMatches ranks the history index once PER task identifier (the
// same focused queries the raw fallback uses) instead of the diluted whole-task string.
// A focused query like "scopeBaseRef" earns the +90 identifier boost cleanly, surfacing the
// decision/learning record that names the exact invariant — which the compound query buries.
// Falls back to the whole-task query for prose tasks that yield no identifiers.
func brainBriefIndexedHistoryMatches(index historyIndex, task string, limit int) []brainTextMatch {
	if limit <= 0 {
		return nil
	}
	ids := brainBriefRawHistoryQueries(task)
	if len(ids) == 0 {
		var out []brainTextMatch
		for _, record := range rankHistoryRecords(index, "history", task, limit) {
			out = append(out, historyRecordTextMatch(record))
		}
		return out
	}
	seen := map[string]struct{}{}
	var matches []brainTextMatch
	for _, id := range ids {
		if len(matches) >= limit {
			break
		}
		for _, record := range rankHistoryRecords(index, "history", id, limit-len(matches)) {
			m := historyRecordTextMatch(record)
			key := brainBriefHistoryMatchKey(m)
			if _, ok := seen[key]; ok {
				continue
			}
			seen[key] = struct{}{}
			matches = append(matches, m)
			if len(matches) >= limit {
				break
			}
		}
	}
	return matches
}

