package cli

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"time"

	"github.com/spf13/cobra"
)

// Regression Radar: turn the brain from a passive librarian into an active reviewer.
// Given a query (task description + identifiers), it compares the CURRENT working tree
// against what the session history asserts the code looked like, and flags lines that
// look like regressions — either a historically-asserted statement that is now absent
// (deleted) or one whose distinctive operand was swapped out (changed).
//
// Why raw history, not the index: the indexed history Summary collapses code to prose, so
// a precise invariant (e.g. `scopeBaseRef+"..HEAD"`) survives only in the RAW session text
// reachable via inspectBrainRawText. The detector therefore reads raw sessions and verifies
// every candidate against the live tree — a finding is only emitted when history asserts an
// expression the current code does not contain verbatim.

const (
	regressionMaxRawHits      = 40   // raw session matches scanned per identifier
	regressionMaxFileBytes    = 1 << 20 // 1 MiB cap when reading a current file
	regressionMinExprLen      = 8    // normalized asserted-expression minimum length
	regressionMaxExprLen      = 120  // normalized asserted-expression maximum length
	regressionMinResidualLen  = 4    // distinctive (non-identifier) residual needed for a "changed" flag
	regressionMaxAnomalies    = 50
)

type regressionAnomaly struct {
	File       string  `json:"file"`
	Line       int     `json:"line,omitempty"`
	Kind       string  `json:"kind"` // "changed" | "deleted"
	Current    string  `json:"current"`
	Expected   string  `json:"expected"`
	Identifier string  `json:"identifier"`
	Confidence float64 `json:"confidence"`
	Reason     string  `json:"reason"`
	Evidence   string  `json:"evidence"` // session path:line that asserts Expected
}

type regressionReport struct {
	GeneratedAt time.Time           `json:"generated_at"`
	Query       string              `json:"query"`
	RepoPath    string              `json:"repo_path"`
	BrainPath   string              `json:"brain_path"`
	Anomalies   []regressionAnomaly `json:"anomalies"`
	Scanned     int                 `json:"scanned_files"`
	Warnings    []string            `json:"warnings,omitempty"`
}

type regressionDetectorOptions struct {
	limit int
	json  bool
}

// assertedExpr is a code expression that the session history asserts, with provenance.
type assertedExpr struct {
	identifier string // the query identifier that surfaced it (lowercased)
	raw        string // human-readable expression as found
	norm       string // normalized (lowercased, whitespace removed) for matching
	evidence   string // session path:line
}

var regressionCodeFilePattern = regexp.MustCompile(`[\w./-]+\.(go|ts|tsx|js|jsx|py|rs|java|kt|swift|c|cc|cpp|h|hpp)`)

// regressionCodeRune reports whether r can be part of a code expression we extract from
// a (space-collapsed) history excerpt.
func regressionCodeRune(r rune) bool {
	switch {
	case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9':
		return true
	}
	switch r {
	case '_', '.', '"', '\'', '+', '-', '=', '(', ')', '[', ']', ':', ',', ' ', '*', '&', '!', '<', '>':
		return true
	}
	return false
}

func regressionNormalizeCode(s string) string {
	s = strings.TrimSpace(s)
	s = strings.TrimLeft(s, "+- \t") // drop diff markers
	var b strings.Builder
	for _, r := range s {
		if r == ' ' || r == '\t' {
			continue
		}
		b.WriteRune(r)
	}
	return strings.ToLower(b.String())
}

func regressionLooksLikeCode(expr string) bool {
	// Must carry a code operator/structure, not just be prose containing the identifier.
	return strings.ContainsAny(expr, "=(+") && !strings.Contains(strings.ToLower(expr), " the ")
}

// regressionExtractAsserted pulls candidate code expressions containing identifier from a
// space-collapsed excerpt: each occurrence is expanded left/right over code runes, trimmed.
func regressionExtractAsserted(identifier, excerpt, evidence string) []assertedExpr {
	lowExcerpt := strings.ToLower(excerpt)
	lowID := strings.ToLower(identifier)
	var out []assertedExpr
	seen := map[string]struct{}{}
	for from := 0; ; {
		idx := strings.Index(lowExcerpt[from:], lowID)
		if idx < 0 {
			break
		}
		pos := from + idx
		// expand over code runes
		start := pos
		for start > 0 {
			r := rune(excerpt[start-1])
			if !regressionCodeRune(r) {
				break
			}
			start--
		}
		end := pos + len(identifier)
		for end < len(excerpt) {
			r := rune(excerpt[end])
			if !regressionCodeRune(r) {
				break
			}
			end++
		}
		raw := strings.TrimSpace(excerpt[start:end])
		raw = strings.Trim(raw, " ,")
		norm := regressionNormalizeCode(raw)
		if len(norm) >= regressionMinExprLen && len(norm) <= regressionMaxExprLen && regressionLooksLikeCode(raw) {
			if _, ok := seen[norm]; !ok {
				seen[norm] = struct{}{}
				out = append(out, assertedExpr{identifier: lowID, raw: raw, norm: norm, evidence: evidence})
			}
		}
		from = pos + len(lowID)
	}
	return out
}

// regressionResidual returns the longest contiguous distinctive substring of the asserted
// expression that does NOT include the identifier — the part that, if found in the current
// code without the identifier, signals the identifier was swapped out (a "changed" regression).
func regressionResidual(norm, lowID string) string {
	parts := strings.Split(norm, lowID)
	best := ""
	for _, p := range parts {
		p = strings.Trim(p, `+="'(),:`)
		if len(p) > len(best) {
			best = p
		}
	}
	return best
}

func detectRegressionAnomalies(brainDir, repoRoot string, semSource *semanticSourceManifest, query string, limit int) ([]regressionAnomaly, int, []string) {
	var warnings []string
	ids := brainBriefRawHistoryQueries(query)
	if len(ids) == 0 {
		return nil, 0, []string{"no code identifiers found in query; pass the failing symbols/terms"}
	}

	// 1. Gather candidate current files + asserted expressions, per identifier.
	candidateFiles := map[string]struct{}{}
	var asserted []assertedExpr
	for _, id := range ids {
		lowID := strings.ToLower(id)
		// (a) current loci via semantic
		if semSource != nil {
			if syms, _, err := semanticContextFacts(brainDir, semSource, lowID, 8, 0); err == nil {
				for _, s := range syms {
					if s.FilePath != "" {
						candidateFiles[s.FilePath] = struct{}{}
					}
				}
			}
		}
		// (b) raw history: asserted expressions + any code files the sessions name
		rep, err := inspectBrainRawText(brainDir, "history", lowID, regressionMaxRawHits)
		if err != nil {
			warnings = append(warnings, fmt.Sprintf("raw history scan failed for %q: %v", id, err))
			continue
		}
		for _, m := range rep.Matches {
			ev := fmt.Sprintf("%s:%d", m.Path, m.Line)
			asserted = append(asserted, regressionExtractAsserted(id, m.Excerpt, ev)...)
			for _, f := range regressionCodeFilePattern.FindAllString(m.Excerpt, -1) {
				candidateFiles[strings.TrimLeft(f, "+-/ ")] = struct{}{}
			}
		}
	}
	if len(asserted) == 0 {
		return nil, 0, append(warnings, "history holds no code-shaped assertions for these identifiers")
	}

	// 2. For each candidate file, verify each asserted expr against the CURRENT tree.
	var anomalies []regressionAnomaly
	scanned := 0
	for file := range candidateFiles {
		clean := filepath.Clean(file)
		if strings.HasPrefix(clean, "..") || filepath.IsAbs(clean) {
			continue
		}
		full := filepath.Join(repoRoot, clean)
		info, err := os.Stat(full)
		if err != nil || info.IsDir() || info.Size() > regressionMaxFileBytes {
			continue
		}
		data, err := os.ReadFile(full)
		if err != nil {
			continue
		}
		scanned++
		content := string(data)
		lines := strings.Split(content, "\n")
		normFile := regressionNormalizeCode(content)

		for _, a := range asserted {
			if strings.Contains(normFile, a.norm) {
				continue // invariant still holds in this file → not a regression
			}
			lowID := a.identifier
			residual := regressionResidual(a.norm, lowID)
			fileHasID := strings.Contains(normFile, lowID)

			if len(residual) >= regressionMinResidualLen && strings.Contains(normFile, residual) && !lineWithBothExists(lines, residual, lowID) {
				// distinctive residual present but identifier swapped out → "changed"
				ln, cur := regressionLocateLine(lines, residual, lowID)
				anomalies = append(anomalies, regressionAnomaly{
					File: clean, Line: ln, Kind: "changed", Current: cur, Expected: a.raw,
					Identifier: a.identifier, Confidence: 0.85, Evidence: a.evidence,
					Reason: fmt.Sprintf("history asserts %q here; current code keeps %q but dropped %q", a.raw, residual, a.identifier),
				})
			} else if fileHasID && regressionAssignmentLike(a.norm) {
				// the identifier lives here but the asserted assignment is gone → "deleted"
				ln, cur := regressionLocateLine(lines, lowID, "")
				anomalies = append(anomalies, regressionAnomaly{
					File: clean, Line: ln, Kind: "deleted", Current: cur, Expected: a.raw,
					Identifier: a.identifier, Confidence: 0.6, Evidence: a.evidence,
					Reason: fmt.Sprintf("history asserts %q in this file; it is absent from the current tree", a.raw),
				})
			}
		}
	}

	anomalies = regressionDedupeRank(anomalies)
	if len(anomalies) > limit {
		anomalies = anomalies[:limit]
	}
	if len(anomalies) > regressionMaxAnomalies {
		anomalies = anomalies[:regressionMaxAnomalies]
	}
	return anomalies, scanned, warnings
}

func regressionAssignmentLike(norm string) bool {
	return strings.Contains(norm, "=") && !strings.Contains(norm, "==")
}

// lineWithBothExists reports whether some current line contains the residual AND the
// identifier together (meaning the invariant still holds line-locally, just reformatted).
func lineWithBothExists(lines []string, residual, lowID string) bool {
	for _, ln := range lines {
		n := regressionNormalizeCode(ln)
		if strings.Contains(n, residual) && strings.Contains(n, lowID) {
			return true
		}
	}
	return false
}

// regressionLocateLine finds the best line for a finding: the first line whose normalized
// form contains `must` (and, if set, NOT `mustNot`); returns 1-based line number + trimmed text.
func regressionLocateLine(lines []string, must, mustNot string) (int, string) {
	for i, ln := range lines {
		n := regressionNormalizeCode(ln)
		if !strings.Contains(n, must) {
			continue
		}
		if mustNot != "" && strings.Contains(n, mustNot) {
			continue
		}
		return i + 1, strings.TrimSpace(ln)
	}
	return 0, ""
}

func regressionDedupeRank(in []regressionAnomaly) []regressionAnomaly {
	seen := map[string]struct{}{}
	var out []regressionAnomaly
	for _, a := range in {
		key := a.File + "|" + a.Kind + "|" + regressionNormalizeCode(a.Expected)
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}
		out = append(out, a)
	}
	sort.SliceStable(out, func(i, j int) bool {
		if out[i].Confidence != out[j].Confidence {
			return out[i].Confidence > out[j].Confidence
		}
		return out[i].File < out[j].File
	})
	return out
}

func runRegressionDetect(ctx context.Context, cmd *cobra.Command, opts Options, ro regressionDetectorOptions, query string) error {
	if ro.limit <= 0 {
		ro.limit = 20
	}
	target := agentSurfaceTarget(opts, nil)
	status, err := buildBrainStatusReport(ctx, opts, target)
	if err != nil {
		return err
	}
	var semSource *semanticSourceManifest
	if status.Manifest != nil && status.Manifest.Sources != nil {
		semSource = status.Manifest.Sources.Semantic
	}
	anomalies, scanned, warnings := detectRegressionAnomalies(status.Brain.Path, status.Repo.Root, semSource, query, ro.limit)
	report := regressionReport{
		GeneratedAt: opts.Now().UTC(),
		Query:       query,
		RepoPath:    status.Repo.Root,
		BrainPath:   status.Brain.Path,
		Anomalies:   anomalies,
		Scanned:     scanned,
		Warnings:    warnings,
	}
	if ro.json {
		return writeJSON(cmd, report)
	}
	out := cmd.OutOrStdout()
	if len(anomalies) == 0 {
		fmt.Fprintf(out, "No suspected regressions for %q (scanned %d files).\n", query, scanned)
		for _, w := range warnings {
			fmt.Fprintf(out, "  note: %s\n", w)
		}
		return nil
	}
	fmt.Fprintf(out, "Suspected regressions for %q:\n", query)
	for _, a := range anomalies {
		fmt.Fprintf(out, "  [%s, conf %.2f] %s:%d\n    expected: %s\n    current:  %s\n    why: %s\n    evidence: %s\n",
			a.Kind, a.Confidence, a.File, a.Line, a.Expected, a.Current, a.Reason, a.Evidence)
	}
	return nil
}

func newInspectRegressionsCommand(opts Options) *cobra.Command {
	ro := regressionDetectorOptions{limit: 20}
	cmd := &cobra.Command{
		Use:   "regressions <query>",
		Short: "Flag suspected regressions by comparing current code to session history",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return runRegressionDetect(cmd.Context(), cmd, opts, ro, args[0])
		},
	}
	cmd.Flags().IntVar(&ro.limit, "limit", 20, "Maximum suspected regressions to return")
	cmd.Flags().BoolVar(&ro.json, "json", false, "Emit machine-readable JSON")
	return cmd
}

