package cli

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"time"

	"github.com/spf13/cobra"
)

// Regression Radar: turn the brain from a passive librarian into an active reviewer.
// Given a query (task description + failing identifiers) it compares the CURRENT working
// tree against what the session history asserts the code looked like, and flags two narrow,
// high-precision shapes of regression:
//
//	changed: history asserts `<id> + "<literal>"` (or a `..` range) at a locus, but the
//	         current tree keeps the distinctive operand while the identifier was swapped out
//	         (e.g. scopeBaseRef+"..HEAD"  ->  "master..HEAD").
//	deleted: history asserts an assignment whose target contains <id> (e.g.
//	         `state.TranscriptPath = resolved`), the identifier still lives in the file, but
//	         that exact assignment is gone.
//
// It reads RAW sessions (inspectBrainRawText), not the index, because the indexed Summary
// collapses code to prose; the precise invariant survives only in raw text. Every candidate is
// verified against the live tree — a finding is emitted only when history asserts something the
// current code does not contain.

const (
	regressionMaxRawHits   = 60
	regressionMaxFileBytes = 1 << 20
	regressionMaxAnomalies = 50
)

type regressionAnomaly struct {
	File       string  `json:"file"`
	Line       int     `json:"line,omitempty"`
	Kind       string  `json:"kind"` // "changed" | "deleted"
	Current    string  `json:"current"`
	Expected   string  `json:"expected"`
	Identifier string  `json:"identifier"`
	Confidence float64 `json:"confidence"`
	Reason     string  `json:"reason"`
	Evidence   string  `json:"evidence"`
}

type regressionReport struct {
	GeneratedAt time.Time           `json:"generated_at"`
	Query       string              `json:"query"`
	RepoPath    string              `json:"repo_path"`
	BrainPath   string              `json:"brain_path"`
	Anomalies   []regressionAnomaly `json:"anomalies"`
	Scanned     int                 `json:"scanned_files"`
	Warnings    []string            `json:"warnings,omitempty"`
}

type regressionDetectorOptions struct {
	limit int
	json  bool
}

// changeSignal: history asserts identifier adjacent to a distinctive operand (string literal
// or `..` range). If the current tree keeps the operand but dropped the identifier → regression.
type changeSignal struct {
	id      string // lowercased identifier
	operand string // distinctive operand, lowercased+despaced (e.g. `..head`)
	raw     string // human-readable asserted expression
	ev      string // session path:line
}

// deleteSignal: history asserts `<target> = <rhs>` where target contains the identifier.
type deleteSignal struct {
	id     string
	target string // normalized LHS up to and including `=` (e.g. `state.transcriptpath=`)
	raw    string
	ev     string
}

var regressionCodeFilePattern = regexp.MustCompile(`[\w./-]+\.(?:go|ts|tsx|js|jsx|py|rs|java|kt|swift|c|cc|cpp|h|hpp)`)

func regressionDespace(s string) string {
	var b strings.Builder
	for _, r := range s {
		if r == ' ' || r == '\t' {
			continue
		}
		b.WriteRune(r)
	}
	return strings.ToLower(b.String())
}

// regressionExtractSignals pulls change + delete signals for one identifier from a (space-
// collapsed) history excerpt using identifier-anchored regexes — far tighter than free-form
// window expansion, so line-number noise and common tokens don't leak in.
func regressionExtractSignals(id, excerpt, ev string) ([]changeSignal, []deleteSignal) {
	q := regexp.QuoteMeta(id)
	// <id> [+] "<literal>"  OR  <id> [+] <a..b range>
	changeRe := regexp.MustCompile(`(?i)` + q + `\s*\+?\s*(?:"([^"]{2,40})"|([A-Za-z0-9_]*\.\.[A-Za-z0-9_]+))`)
	// (a.b.)*<...id...> = <rhs>   (single '=', target path contains the identifier)
	assignRe := regexp.MustCompile(`(?i)((?:[A-Za-z0-9_]+\.)*[A-Za-z0-9_]*` + q + `[A-Za-z0-9_]*)\s*(:?=)\s*([^=;,{}\n][^;,{}\n]{0,48})`)

	var changes []changeSignal
	seenC := map[string]struct{}{}
	for _, m := range changeRe.FindAllStringSubmatch(excerpt, -1) {
		operand := m[1]
		if operand == "" {
			operand = m[2]
		}
		operand = regressionDespace(operand)
		// distinctive: a string literal or a `..` range, length >= 4
		if len(operand) < 4 {
			continue
		}
		if _, ok := seenC[operand]; ok {
			continue
		}
		seenC[operand] = struct{}{}
		changes = append(changes, changeSignal{id: id, operand: operand, raw: strings.TrimSpace(m[0]), ev: ev})
	}

	var deletes []deleteSignal
	seenD := map[string]struct{}{}
	for _, m := range assignRe.FindAllStringSubmatch(excerpt, -1) {
		lhs := regressionDespace(m[1])
		op := m[2]
		if op == "==" || !strings.Contains(lhs, id) {
			continue
		}
		target := lhs + op // e.g. state.transcriptpath= or x:=
		if _, ok := seenD[target]; ok {
			continue
		}
		seenD[target] = struct{}{}
		raw := strings.TrimSpace(m[1] + " " + op + " " + strings.TrimSpace(m[3]))
		deletes = append(deletes, deleteSignal{id: id, target: target, raw: raw, ev: ev})
	}
	return changes, deletes
}

func detectRegressionAnomalies(brainDir, repoRoot string, semSource *semanticSourceManifest, query string, limit int) ([]regressionAnomaly, int, []string) {
	var warnings []string
	ids := brainBriefRawHistoryQueries(query)
	if len(ids) == 0 {
		return nil, 0, []string{"no code identifiers found in query; pass the failing symbols/terms"}
	}

	candidateFiles := map[string]struct{}{}
	var changes []changeSignal
	var deletes []deleteSignal
	for _, rawID := range ids {
		id := strings.ToLower(rawID)
		if semSource != nil {
			if syms, _, err := semanticContextFacts(brainDir, semSource, id, 8, 0); err == nil {
				for _, s := range syms {
					if s.FilePath != "" {
						candidateFiles[s.FilePath] = struct{}{}
					}
				}
			}
		}
		rep, err := inspectBrainRawText(brainDir, "history", id, regressionMaxRawHits)
		if err != nil {
			warnings = append(warnings, fmt.Sprintf("raw history scan failed for %q: %v", rawID, err))
			continue
		}
		for _, m := range rep.Matches {
			ev := fmt.Sprintf("%s:%d", m.Path, m.Line)
			c, d := regressionExtractSignals(id, m.Excerpt, ev)
			changes = append(changes, c...)
			deletes = append(deletes, d...)
			for _, f := range regressionCodeFilePattern.FindAllString(m.Excerpt, -1) {
				candidateFiles[strings.TrimLeft(f, "+-/ ")] = struct{}{}
			}
		}
	}
	if len(changes) == 0 && len(deletes) == 0 {
		return nil, 0, append(warnings, "history holds no precise code assertions for these identifiers")
	}

	var anomalies []regressionAnomaly
	scanned := 0
	for file := range candidateFiles {
		clean := filepath.Clean(file)
		if strings.HasPrefix(clean, "..") || filepath.IsAbs(clean) {
			continue
		}
		full := filepath.Join(repoRoot, clean)
		info, err := os.Stat(full)
		if err != nil || info.IsDir() || info.Size() > regressionMaxFileBytes {
			continue
		}
		data, err := os.ReadFile(full)
		if err != nil {
			continue
		}
		scanned++
		lines := strings.Split(string(data), "\n")
		normLines := make([]string, len(lines))
		for i, ln := range lines {
			normLines[i] = regressionDespace(ln)
		}
		fileHas := func(needle string) bool {
			for _, n := range normLines {
				if strings.Contains(n, needle) {
					return true
				}
			}
			return false
		}

		for _, c := range changes {
			// invariant still holds if some line has BOTH operand and identifier.
			intact, swapped, swapLine := false, false, -1
			for i, n := range normLines {
				hasOp := strings.Contains(n, c.operand)
				if hasOp && strings.Contains(n, c.id) {
					intact = true
					break
				}
				if hasOp && !strings.Contains(n, c.id) && swapLine == -1 {
					swapped, swapLine = true, i
				}
			}
			if intact || !swapped {
				continue
			}
			anomalies = append(anomalies, regressionAnomaly{
				File: clean, Line: swapLine + 1, Kind: "changed",
				Current: strings.TrimSpace(lines[swapLine]), Expected: c.raw,
				Identifier: c.id, Confidence: 0.85, Evidence: c.ev,
				Reason: fmt.Sprintf("history asserts %q here; the current line keeps %q but dropped %q", c.raw, c.operand, c.id),
			})
		}

		for _, d := range deletes {
			if fileHas(d.target) || !fileHas(d.id) {
				continue // assignment still present, or identifier doesn't live here
			}
			ln, cur := regressionLocateLine(normLines, lines, d.id)
			anomalies = append(anomalies, regressionAnomaly{
				File: clean, Line: ln, Kind: "deleted",
				Current: cur, Expected: d.raw,
				Identifier: d.id, Confidence: 0.6, Evidence: d.ev,
				Reason: fmt.Sprintf("history asserts `%s` in this file; that assignment is absent from the current tree", d.raw),
			})
		}
	}

	anomalies = regressionDedupeRank(anomalies)
	if limit > 0 && len(anomalies) > limit {
		anomalies = anomalies[:limit]
	}
	if len(anomalies) > regressionMaxAnomalies {
		anomalies = anomalies[:regressionMaxAnomalies]
	}
	return anomalies, scanned, warnings
}

func regressionLocateLine(normLines, lines []string, needle string) (int, string) {
	for i, n := range normLines {
		if strings.Contains(n, needle) {
			return i + 1, strings.TrimSpace(lines[i])
		}
	}
	return 0, "(absent)"
}

func regressionDedupeRank(in []regressionAnomaly) []regressionAnomaly {
	seen := map[string]struct{}{}
	var out []regressionAnomaly
	for _, a := range in {
		key := a.File + "|" + a.Kind + "|" + regressionDespace(a.Expected)
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}
		out = append(out, a)
	}
	sort.SliceStable(out, func(i, j int) bool {
		if out[i].Confidence != out[j].Confidence {
			return out[i].Confidence > out[j].Confidence
		}
		return out[i].File < out[j].File
	})
	return out
}

func runRegressionDetect(ctx context.Context, cmd *cobra.Command, opts Options, ro regressionDetectorOptions, query string) error {
	if ro.limit <= 0 {
		ro.limit = 20
	}
	target := agentSurfaceTarget(opts, nil)
	status, err := buildBrainStatusReport(ctx, opts, target)
	if err != nil {
		return err
	}
	var semSource *semanticSourceManifest
	if status.Manifest != nil && status.Manifest.Sources != nil {
		semSource = status.Manifest.Sources.Semantic
	}
	anomalies, scanned, warnings := detectRegressionAnomalies(status.Brain.Path, status.Repo.Root, semSource, query, ro.limit)
	report := regressionReport{
		GeneratedAt: opts.Now().UTC(),
		Query:       query,
		RepoPath:    status.Repo.Root,
		BrainPath:   status.Brain.Path,
		Anomalies:   anomalies,
		Scanned:     scanned,
		Warnings:    warnings,
	}
	if ro.json {
		return writeJSON(cmd, report)
	}
	out := cmd.OutOrStdout()
	if len(anomalies) == 0 {
		fmt.Fprintf(out, "No suspected regressions for %q (scanned %d files).\n", query, scanned)
		for _, w := range warnings {
			fmt.Fprintf(out, "  note: %s\n", w)
		}
		return nil
	}
	fmt.Fprintf(out, "Suspected regressions for %q:\n", query)
	for _, a := range anomalies {
		fmt.Fprintf(out, "  [%s, conf %.2f] %s:%d\n    expected: %s\n    current:  %s\n    why: %s\n    evidence: %s\n",
			a.Kind, a.Confidence, a.File, a.Line, a.Expected, a.Current, a.Reason, a.Evidence)
	}
	return nil
}

func newInspectRegressionsCommand(opts Options) *cobra.Command {
	ro := regressionDetectorOptions{limit: 20}
	cmd := &cobra.Command{
		Use:   "regressions <query>",
		Short: "Flag suspected regressions by comparing current code to session history",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return runRegressionDetect(cmd.Context(), cmd, opts, ro, args[0])
		},
	}
	cmd.Flags().IntVar(&ro.limit, "limit", 20, "Maximum suspected regressions to return")
	cmd.Flags().BoolVar(&ro.json, "json", false, "Emit machine-readable JSON")
	return cmd
}

