	target string // normalized LHS + assignment op (e.g. `state.transcriptpath=`)
	rhs    string // despaced right-hand side token (e.g. `resolved`) — used to locate the home file
	raw    string
	ev     string
}

type candFile struct {
	clean string
	lines []string
	norm  []string
}

