176	// regressionScanHistory walks the raw brain (sessions + exports) once and extracts change/delete
177	// signals for the given identifiers from EVERY matching line — not a capped top-N — so rare but
178	// precise invariants are not lost. Bounded by a generous file cap and a distinct-signal cap.
179	func regressionScanHistory(brainDir string, ids []string) ([]changeSignal, []deleteSignal, map[string]struct{}) {
180		const (
181			maxFiles       = 20000
182			maxLineBytes   = 4 * 1024 * 1024
183			maxSignalsEach = 400
184		)
185		lowIDs := make([]string, 0, len(ids))
186		for _, id := range ids {
187			lowIDs = append(lowIDs, strings.ToLower(id))
188		}
189		var changes []changeSignal
190		var deletes []deleteSignal
191		files := map[string]struct{}{}
192		seenC := map[string]struct{}{}
193		seenD := map[string]struct{}{}
194		scanned := 0
195		_ = filepath.WalkDir(brainDir, func(path string, d fs.DirEntry, err error) error {
196			if err != nil {
197				return nil
198			}
199			if d.IsDir() {
200				if n := d.Name(); n == semanticDirName || n == ".git" {
201					return filepath.SkipDir
202				}
203				return nil
204			}
205			if scanned >= maxFiles || (len(seenC) >= maxSignalsEach && len(seenD) >= maxSignalsEach) {
206				return filepath.SkipAll
207			}
208			switch filepath.Ext(path) {
209			case ".jsonl", ".json", ".md", ".txt":
210			default:
211				return nil
212			}
213			rel, _ := filepath.Rel(brainDir, path)
214			relSlash := filepath.ToSlash(rel)
215			if relSlash == "manifest.json" || strings.HasPrefix(relSlash, "seed/") {
216				return nil
217			}
218			f, openErr := os.Open(path)
219			if openErr != nil {
220				return nil
221			}
222			defer f.Close()
223			scanned++
224			sc := bufio.NewScanner(f)
225			sc.Buffer(make([]byte, 0, 64*1024), maxLineBytes)
226			lineNo := 0
227			for sc.Scan() {
228				lineNo++
229				line := sc.Text()
230				low := strings.ToLower(line)
231				matched := false
232				for _, id := range lowIDs {
233					if !strings.Contains(low, id) {
234						continue
235					}
236					matched = true
237					ex := normalizeHistoryTextForExcerpt(line)
238					ev := relSlash + ":" + strconv.Itoa(lineNo)
239					c, dl := regressionExtractSignals(id, ex, ev)
240					for _, s := range c {
241						if _, ok := seenC[s.id+"|"+s.operand]; !ok {
242							seenC[s.id+"|"+s.operand] = struct{}{}
243							changes = append(changes, s)
244						}
245					}
246					for _, s := range dl {
247						k := s.target + "|" + s.rhs
248						if _, ok := seenD[k]; !ok {
249							seenD[k] = struct{}{}
250							deletes = append(deletes, s)
251						}
252					}
253				}
254				if matched {
255					for _, fn := range regressionCodeFilePattern.FindAllString(line, -1) {
256						files[strings.TrimLeft(fn, "+-/ ")] = struct{}{}
257					}
258				}
259			}
260			return nil
261		})
262		return changes, deletes, files
263	}
