265	func detectRegressionAnomalies(brainDir, repoRoot string, semSource *semanticSourceManifest, query string, limit int, includeDeletions bool) ([]regressionAnomaly, int, []string) {
266		var warnings []string
267		ids := brainBriefRawHistoryQueries(query)
268		if len(ids) == 0 {
269			return nil, 0, []string{"no code identifiers found in query; pass the failing symbols/terms"}
270		}
271	
272		candidateFiles := map[string]struct{}{}
273		semanticRank := map[string]int{} // clean path -> best (lowest) semantic rank; lower = stronger locus
274		for _, rawID := range ids {
275			id := strings.ToLower(rawID)
276			if semSource != nil {
277				if syms, _, err := semanticContextFacts(brainDir, semSource, id, 8, 0); err == nil {
278					for rank, s := range syms {
279						if s.FilePath == "" {
280							continue
281						}
282						candidateFiles[s.FilePath] = struct{}{}
283						c := filepath.Clean(s.FilePath)
284						if r, ok := semanticRank[c]; !ok || rank < r {
285							semanticRank[c] = rank
286						}
287					}
288				}
289			}
290		}
291		// Targeted history scan: walk the raw sessions once, keeping only signal-bearing lines (so a
292		// rare invariant isn't lost behind thousands of plain identifier mentions, as a capped
293		// generic scan would). Also collects the code files those sessions name.
294		changes, deletes, namedFiles := regressionScanHistory(brainDir, ids)
295		for f := range namedFiles {
296			candidateFiles[f] = struct{}{}
297		}
298		if len(changes) == 0 && len(deletes) == 0 {
299			return nil, 0, append(warnings, "history holds no precise code assertions for these identifiers")
300		}
301	
302		// Load all candidate files once.
303		var files []candFile
304		for file := range candidateFiles {
305			clean := filepath.Clean(file)
306			if strings.HasPrefix(clean, "..") || filepath.IsAbs(clean) {
307				continue
308			}
309			full := filepath.Join(repoRoot, clean)
310			info, err := os.Stat(full)
311			if err != nil || info.IsDir() || info.Size() > regressionMaxFileBytes {
312				continue
313			}
314			data, err := os.ReadFile(full)
315			if err != nil {
316				continue
317			}
318			lines := strings.Split(string(data), "\n")
319			norm := make([]string, len(lines))
320			for i, ln := range lines {
321				norm[i] = regressionDespace(ln)
322			}
323			rank, isSem := semanticRank[clean]
324			if !isSem {
325				rank = 1 << 30
326			}
327			files = append(files, candFile{clean: clean, lines: lines, norm: norm, semantic: isSem, rank: rank, isTest: regressionIsTestPath(clean)})
328		}
329		if len(files) == 0 {
330			return nil, 0, append(warnings, "no current files to verify against (semantic index missing?)")
331		}
332		// Deterministic, locus-prioritized order: implementation before tests, then by semantic rank
333		// (the strongest fix-site first), then path — so a finding lands on the actual fix site, not a
334		// random file that happens to share a common operand like `..HEAD`.
335		sort.SliceStable(files, func(i, j int) bool {
336			if files[i].isTest != files[j].isTest {
337				return !files[i].isTest
338			}
339			if files[i].rank != files[j].rank {
340				return files[i].rank < files[j].rank
341			}
342			return files[i].clean < files[j].clean
343		})
344	
345		anyLineBoth := func(a, b string) bool {
346			for _, f := range files {
347				for _, n := range f.norm {
348					if strings.Contains(n, a) && strings.Contains(n, b) {
349						return true
350					}
351				}
352			}
353			return false
354		}
355		anyHas := func(needle string) bool {
356			for _, f := range files {
357				for _, n := range f.norm {
358					if strings.Contains(n, needle) {
359						return true
360					}
361				}
362			}
363			return false
364		}
365	
366		var anomalies []regressionAnomaly
367	
368		for _, c := range dedupeChanges(changes) {
369			if anyLineBoth(c.operand, c.id) {
370				continue // invariant still holds somewhere
371			}
372			for _, f := range files { // locate the swap: operand present, identifier gone
373				if f.isTest {
374					continue // a test's `..HEAD` is not the regressed implementation site
375				}
376				found := false
377				for i, n := range f.norm {
378					if regressionIsComment(f.lines[i]) {
379						continue // prose mentions of a range like `main...HEAD` are not the regression
380					}
381					if strings.Contains(n, c.operand) && !strings.Contains(n, c.id) {
382						anomalies = append(anomalies, regressionAnomaly{
383							File: f.clean, Line: i + 1, Kind: "changed",
384							Current: strings.TrimSpace(f.lines[i]), Expected: c.raw,
385							Identifier: c.id, Confidence: 0.85, Evidence: c.ev,
386							Reason: fmt.Sprintf("history asserts %q; this line keeps %q but dropped %q", c.raw, c.operand, c.id),
387						})
388						found = true
389						break
390					}
391				}
392				if found {
393					break
394				}
395			}
396		}
397	
398		for _, d := range dedupeDeletes(deletes) {
399			if !includeDeletions {
400				break // deletions are higher-recall but noisier (benign churn) — opt-in only
401			}
402			// The SPECIFIC assignment (target + its RHS) must be absent everywhere — a different
403			// assignment to the same field in another file is not this regression.
404			if anyHas(d.target+d.rhs) || !anyHas(d.id) {
405				continue
406			}
407			// Locate the home file: prefer one that also holds the RHS token (the natural site of
408			// the assignment), else the first file where the identifier appears.
409			home, line, cur := regressionHomeFile(files, d.id, d.rhs)
410			if home == "" {
411				continue
412			}
413			anomalies = append(anomalies, regressionAnomaly{
414				File: home, Line: line, Kind: "deleted",
415				Current: cur, Expected: d.raw,
416				Identifier: d.id, Confidence: 0.65, Evidence: d.ev,
417				Reason: fmt.Sprintf("history asserts `%s` but that assignment is absent everywhere in the current tree", d.raw),
418			})
419		}
420	
421		anomalies = regressionDedupeRank(anomalies)
422		if limit > 0 && len(anomalies) > limit {
423			anomalies = anomalies[:limit]
424		}
425		if len(anomalies) > regressionMaxAnomalies {
426			anomalies = anomalies[:regressionMaxAnomalies]
427		}
428		return anomalies, len(files), warnings
429	}
