432	// containing both the identifier and the RHS token, else the first file holding the identifier.
433	func regressionHomeFile(files []candFile, id, rhs string) (string, int, string) {
434		if rhs != "" {
435			for _, f := range files {
436				if !fileHasNorm(f.norm, rhs) {
437					continue
438				}
439				for i, n := range f.norm {
440					if strings.Contains(n, id) {
441						return f.clean, i + 1, strings.TrimSpace(f.lines[i])
442					}
443				}
444			}
445		}
446		for _, f := range files {
447			for i, n := range f.norm {
448				if strings.Contains(n, id) {
449					return f.clean, i + 1, strings.TrimSpace(f.lines[i])
450				}
451			}
452		}
453		return "", 0, "(absent)"
454	}
