575			}
576			return nil
577		}
578		fmt.Fprintf(out, "Suspected regressions for %q:\n", query)
579		for _, a := range anomalies {
580			fmt.Fprintf(out, "  [%s, conf %.2f] %s:%d\n    expected: %s\n    current:  %s\n    why: %s\n    evidence: %s\n",
581				a.Kind, a.Confidence, a.File, a.Line, a.Expected, a.Current, a.Reason, a.Evidence)
582		}
