603	// ---- Diff-less review: a review-shaped presentation over the regression detector ----
604	//
605	// The building block `entire review` would consume when entire-brain is installed: instead of a
606	// branch-vs-base diff, it reviews the current working tree against the brain's memory and reports
607	// suspected regressions as review findings. Same detector, reviewer-facing framing.
608	
609	type reviewFinding struct {
610		Severity   string  `json:"severity"` // high | medium | low (from detector confidence)
611		File       string  `json:"file"`
612		Line       int     `json:"line,omitempty"`
613		Title      string  `json:"title"`
614		Detail     string  `json:"detail"`
615		Evidence   string  `json:"evidence"`
616		Confidence float64 `json:"confidence"`
617	}
618	
619	type reviewReport struct {
620		GeneratedAt time.Time       `json:"generated_at"`
621		Mode        string          `json:"mode"`
622		Query       string          `json:"query"`
623		RepoPath    string          `json:"repo_path"`
624		BrainPath   string          `json:"brain_path"`
625		Summary     string          `json:"summary"`
626		Findings    []reviewFinding `json:"findings"`
627		Warnings    []string        `json:"warnings,omitempty"`
628	}
629	
630	func regressionSeverity(conf float64) string {
631		switch {
632		case conf >= 0.8:
633			return "high"
634		case conf >= 0.6:
635			return "medium"
636		default:
637			return "low"
638		}
639	}
640	
641	func anomalyToReviewFinding(a regressionAnomaly) reviewFinding {
642		detail := "suspected regression at this location — verify against the brain's history."
643		if a.Expected != "" {
644			detail = fmt.Sprintf("history shows `%s`; current is `%s` — verify this change is intentional (could also be a rename).", a.Expected, a.Current)
645		}
646		return reviewFinding{
647			Severity:   regressionSeverity(a.Confidence),
648			File:       a.File,
649			Line:       a.Line,
650			Title:      fmt.Sprintf("Suspected regression: `%s` %s", a.Identifier, a.Kind),
651			Detail:     detail,
652			Evidence:   a.Evidence,
653			Confidence: a.Confidence,
654		}
655	}
