657	func runBrainReview(ctx context.Context, cmd *cobra.Command, opts Options, ro regressionDetectorOptions, query string) error {
658		if ro.limit <= 0 {
659			ro.limit = 20
660		}
661		target := agentSurfaceTarget(opts, nil)
662		status, err := buildBrainStatusReport(ctx, opts, target)
663		if err != nil {
664			return err
665		}
666		var semSource *semanticSourceManifest
667		if status.Manifest != nil && status.Manifest.Sources != nil {
668			semSource = status.Manifest.Sources.Semantic
669		}
670		anomalies, _, warnings := detectRegressionAnomalies(status.Brain.Path, status.Repo.Root, semSource, query, ro.limit, ro.includeDeletions)
671		findings := make([]reviewFinding, 0, len(anomalies))
672		for _, a := range anomalies {
673			findings = append(findings, anomalyToReviewFinding(a))
674		}
675		summary := "Diff-less review: no suspected regressions (current tree matches the brain's memory)."
676		if len(findings) > 0 {
677			summary = fmt.Sprintf("Diff-less review: %d suspected regression(s) — verify each before acting.", len(findings))
678		}
679		report := reviewReport{
680			GeneratedAt: opts.Now().UTC(),
681			Mode:        "diff-less (brain memory vs current tree)",
682			Query:       query,
683			RepoPath:    status.Repo.Root,
684			BrainPath:   status.Brain.Path,
685			Summary:     summary,
686			Findings:    findings,
687			Warnings:    warnings,
688		}
689		if ro.json {
690			return writeJSON(cmd, report)
691		}
692		out := cmd.OutOrStdout()
693		fmt.Fprintln(out, report.Summary)
694		for _, f := range findings {
695			fmt.Fprintf(out, "\n  [%s] %s\n    %s:%d\n    %s\n    evidence: %s\n",
696				strings.ToUpper(f.Severity), f.Title, f.File, f.Line, f.Detail, f.Evidence)
697		}
698		for _, w := range warnings {
699			fmt.Fprintf(out, "  note: %s\n", w)
700		}
701		return nil
702	}
