// Package review — see env.go for package-level rationale.
//
// brain.go implements the diff-less review mode: a graceful upgrade that turns
// on when the entire-brain plugin is installed. A normal `entire review` needs
// a branch-vs-base diff to review. When there is no diff (no commits unique to
// the branch and no uncommitted changes) and entire-brain is available, the
// brain reviews the working tree against the session history instead — the same
// way entire-brain itself gains power from entire-sem when that is installed.
//
// The brain query and the exec/parse of `entire-brain review --json` live in
// the cli package (review_brain_bridge.go) and are injected as
// Deps.DiffLessReviewContext, so this package stays testable without a brain.

package review

import (
	"context"
	"fmt"
	"io"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/gitrepo"
)

// applyDiffLessReview augments ctxResult with brain-derived suspected
// regressions when the review is diff-less (or --diff-less forced it) and the
// brain hook is wired. It is a no-op — returning ctxResult unchanged — when the
// hook is absent, the scope is non-empty (and not forced), no query can be
// derived, or the brain returns nothing. That keeps it a pure graceful upgrade:
// review behaves exactly as before whenever the brain is not contributing.
func applyDiffLessReview(ctx context.Context, deps Deps, worktreeRoot, baseOverride, perRunPrompt string, forced bool, ctxResult ContextResult, out io.Writer) ContextResult {
	if deps.DiffLessReviewContext == nil {
		return ctxResult
	}

	branch, empty := scopeBranchAndEmptiness(ctx, worktreeRoot, baseOverride)
	if !forced && !empty {
		return ctxResult
	}

	query := deriveDiffLessQuery(ctxResult, branch, perRunPrompt)
	if strings.TrimSpace(query) == "" {
		return ctxResult
	}
	section := deps.DiffLessReviewContext(ctx, worktreeRoot, query)
	if strings.TrimSpace(section) == "" {
		return ctxResult
	}
	fmt.Fprintln(out, "diff-less mode (entire-brain): injecting suspected regressions from brain memory")
	ctxResult.Prompt = joinDiffLessSection(ctxResult.Prompt, section)
	return ctxResult
}

// scopeBranchAndEmptiness opens the repo once and reports the current branch
// name and whether the review scope is empty (no commits unique to the branch
// and no uncommitted changes). On any error it reports ("", false) so the
// caller does not force diff-less mode on uncertainty.
func scopeBranchAndEmptiness(ctx context.Context, worktreeRoot, baseOverride string) (string, bool) {
	repo, err := gitrepo.OpenPath(worktreeRoot)
	if err != nil {
		return "", false
	}
	defer repo.Close()
	branch := currentBranchName(repo)
	stats, statsErr := ComputeScopeStats(ctx, repo, baseOverride)
	if statsErr != nil {
		return branch, false
	}
	return branch, stats.Commits == 0 && stats.Uncommitted == 0
}

// deriveDiffLessQuery builds the brain query from the signals available when
// there is no diff to mine: the per-run prompt, the in-scope checkpoint
// summaries, and the branch name (slug separators turned into spaces so the
// detector sees word-ish tokens). The brain extracts code identifiers from
// this text to localize suspected regressions.
func deriveDiffLessQuery(ctxResult ContextResult, branch, perRunPrompt string) string {
	var parts []string
	if s := strings.TrimSpace(perRunPrompt); s != "" {
		parts = append(parts, s)
	}
	for _, item := range ctxResult.CheckpointItems {
		if s := strings.TrimSpace(item.Summary); s != "" {
			parts = append(parts, s)
		}
	}
	if b := strings.TrimSpace(branch); b != "" {
		parts = append(parts, strings.NewReplacer("/", " ", "-", " ", "_", " ").Replace(b))
	}
	return strings.Join(parts, " ")
}

// joinDiffLessSection appends the brain section as its own paragraph after the
// existing checkpoint/session context, matching joinReviewContextSections'
// blank-line convention so it lands cleanly in ComposeReviewPrompt.
func joinDiffLessSection(base, section string) string {
	base = strings.TrimRight(base, "\n\r ")
	section = strings.TrimSpace(section)
	switch {
	case section == "":
		return base
	case base == "":
		return section
	default:
		return base + "\n\n" + section
	}
}

