package cli

// review_brain_bridge.go wires the diff-less review mode into review.Deps.
// When the entire-brain plugin is installed (discoverable on PATH as the
// `entire-brain` plugin binary), the review subpackage calls this to obtain a
// "suspected regressions" context section derived from session memory — the
// graceful upgrade Thomas asked for: `entire review` gains a diff-less mode
// when the brain is installed, the same way entire-brain gains power from
// entire-sem. When the brain is absent or finds nothing, this returns "" and
// review proceeds exactly as before.

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/logging"
)

const (
	diffLessBrainBinary  = "entire-brain"
	diffLessFindingLimit = 10
)

// diffLessFinding mirrors the brain's reviewReport finding shape (the stable
// `entire-brain review --json` contract). Only the fields review needs.
type diffLessFinding struct {
	Severity   string  `json:"severity"`
	File       string  `json:"file"`
	Line       int     `json:"line"`
	Title      string  `json:"title"`
	Detail     string  `json:"detail"`
	Evidence   string  `json:"evidence"`
	Confidence float64 `json:"confidence"`
}

type diffLessReport struct {
	Summary  string            `json:"summary"`
	Findings []diffLessFinding `json:"findings"`
}

// diffLessReviewContext is wired into review.Deps.DiffLessReviewContext. It
// shells the entire-brain plugin's diff-less review (`entire-brain review
// <query> --json`) scoped to worktreeRoot and returns a formatted context
// section, or "" when the brain is unavailable, errors, or reports nothing.
func diffLessReviewContext(ctx context.Context, worktreeRoot, query string) string {
	binPath, err := exec.LookPath(diffLessBrainBinary)
	if err != nil {
		return "" // brain not installed — graceful no-op
	}
	if strings.TrimSpace(query) == "" {
		return ""
	}
	cmd := exec.CommandContext(ctx, binPath, "review", query,
		"--json", "--limit", fmt.Sprintf("%d", diffLessFindingLimit))
	cmd.Env = append(os.Environ(), "ENTIRE_REPO_ROOT="+worktreeRoot)
	out, runErr := cmd.Output()
	if runErr != nil {
		logging.Debug(ctx, "diff-less brain review failed", "error", runErr.Error())
		return ""
	}
	var report diffLessReport
	if err := json.Unmarshal(out, &report); err != nil {
		logging.Debug(ctx, "diff-less brain review: parse output", "error", err.Error())
		return ""
	}
	return formatDiffLessReview(report)
}

// formatDiffLessReview renders the brain findings as a review-context section.
// Pure (no I/O) so it is unit-testable. Returns "" when there are no findings.
func formatDiffLessReview(report diffLessReport) string {
	if len(report.Findings) == 0 {
		return ""
	}
	var b strings.Builder
	fmt.Fprintf(&b, "Diff-less review (entire-brain) — %d suspected regression(s) from session memory; verify each before acting:\n",
		len(report.Findings))
	for _, f := range report.Findings {
		sev := strings.ToUpper(strings.TrimSpace(f.Severity))
		if sev == "" {
			sev = "LOW"
		}
		fmt.Fprintf(&b, "  [%s] %s\n", sev, strings.TrimSpace(f.Title))
		if f.File != "" {
			if f.Line > 0 {
				fmt.Fprintf(&b, "    %s:%d\n", f.File, f.Line)
			} else {
				fmt.Fprintf(&b, "    %s\n", f.File)
			}
		}
		if d := strings.TrimSpace(f.Detail); d != "" {
			fmt.Fprintf(&b, "    %s\n", d)
		}
		if e := strings.TrimSpace(f.Evidence); e != "" {
			fmt.Fprintf(&b, "    evidence: %s\n", e)
		}
	}
	return strings.TrimRight(b.String(), "\n")
}

