// Package investigate — brain.go implements the brain upgrade for
// `entire investigate`: when the entire-brain plugin is installed, suspected
// regressions from session memory are folded into the per-turn AlwaysPrompt so
// every brainstorming agent sees what history says the code used to be. Unlike
// review there is no diff concept here — the investigation topic is always the
// query — so the hook fires whenever the brain is available. The exec/parse of
// `entire-brain review --json` lives in the cli package and is injected as
// Deps.DiffLessInvestigateContext, keeping this package testable without a brain.

package investigate

import (
	"context"
	"strings"
)

// augmentAlwaysPromptWithBrain appends brain-derived suspected regressions to
// the investigation's AlwaysPrompt. Returns alwaysPrompt unchanged when the
// hook is absent or the brain contributes nothing (graceful no-op).
func augmentAlwaysPromptWithBrain(ctx context.Context, deps Deps, worktreeRoot, topic, alwaysPrompt string) string {
	if deps.DiffLessInvestigateContext == nil {
		return alwaysPrompt
	}
	section := deps.DiffLessInvestigateContext(ctx, worktreeRoot, topic)
	if strings.TrimSpace(section) == "" {
		return alwaysPrompt
	}
	if strings.TrimSpace(alwaysPrompt) == "" {
		return section
	}
	return alwaysPrompt + "\n\n" + section
}

