package review

import "testing"

func TestDeriveDiffLessQuery(t *testing.T) {
	q := deriveDiffLessQuery(ContextResult{
		CheckpointItems: []CheckpointScopeItem{
			{ID: "a1b2c3d4", Summary: "fix review scope base ref"},
			{ID: "b2c3d4e5", Summary: ""},
		},
	}, "claude/diff-less-brain", "scopeBaseRef")
	for _, want := range []string{"scopeBaseRef", "fix review scope base ref", "claude diff less brain"} {
		if !contains(q, want) {
			t.Fatalf("query %q missing %q", q, want)
		}
	}

	if got := deriveDiffLessQuery(ContextResult{}, "", ""); got != "" {
		t.Fatalf("empty inputs should yield empty query, got %q", got)
	}
}

func TestJoinDiffLessSection(t *testing.T) {
	if got := joinDiffLessSection("base", "section"); got != "base\n\nsection" {
		t.Fatalf("join = %q", got)
	}
	if got := joinDiffLessSection("", "section"); got != "section" {
		t.Fatalf("empty base join = %q", got)
	}
	if got := joinDiffLessSection("base\n\n", ""); got != "base" {
		t.Fatalf("empty section join = %q", got)
	}
}

func contains(haystack, needle string) bool {
	return len(haystack) >= len(needle) && (haystack == needle || indexOf(haystack, needle) >= 0)
}

func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}

