package review_test

import (
	"bytes"
	"context"
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/review"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
	"github.com/entireio/cli/cmd/entire/cli/settings"
)

// TestDiffLessReviewInjectsBrainSection verifies that --diff-less drives the
// DiffLessReviewContext hook and folds its section into the RunConfig the
// reviewer receives — alongside (not replacing) the normal checkpoint context.
// The existing cmd_test.go cases, which leave the hook nil and assert
// CheckpointContext is unchanged, cover the graceful no-op (brain absent).
func TestDiffLessReviewInjectsBrainSection(t *testing.T) {
	setupCmdTestRepo(t)
	if err := review.SaveReviewConfig(context.Background(), map[string]settings.ReviewConfig{
		testAgentName: {Skills: []string{"/review"}},
	}); err != nil {
		t.Fatal(err)
	}
	reviewer := &captureRunConfigReviewer{name: testAgentName}
	var gotQuery string
	const brainSection = "Diff-less review (entire-brain) — 1 suspected regression(s) from session memory; verify each before acting:\n  [HIGH] Suspected regression: `scopeBaseRef` changed"
	deps := review.Deps{
		GetAgentsWithHooksInstalled: func(_ context.Context) []types.AgentName {
			return []types.AgentName{testAgentName}
		},
		NewSilentError:          func(err error) error { return err },
		HeadHasReviewCheckpoint: func(_ context.Context) (bool, string) { return false, "" },
		ReviewCheckpointContext: func(_ context.Context, _ string, _ string) review.ContextResult {
			return review.ContextResult{
				Prompt:          "base ctx",
				CheckpointItems: []review.CheckpointScopeItem{{ID: "abc12345", Summary: "fix review scope base ref"}},
			}
		},
		DiffLessReviewContext: func(_ context.Context, _ string, query string) string {
			gotQuery = query
			return brainSection
		},
		ReviewerFor: func(agentName string) reviewtypes.AgentReviewer {
			if agentName == testAgentName {
				return reviewer
			}
			return nil
		},
	}
	out := &bytes.Buffer{}
	cmd := review.NewCommand(deps)
	cmd.SetOut(out)
	cmd.SetErr(&bytes.Buffer{})
	cmd.SetArgs([]string{"--diff-less"})
	if err := cmd.Execute(); err != nil {
		t.Fatalf("execute: %v", err)
	}
	if !strings.Contains(reviewer.got.CheckpointContext, "base ctx") {
		t.Errorf("CheckpointContext dropped the normal context: %q", reviewer.got.CheckpointContext)
	}
	if !strings.Contains(reviewer.got.CheckpointContext, "Suspected regression") {
		t.Errorf("CheckpointContext missing the brain section: %q", reviewer.got.CheckpointContext)
	}
	if strings.TrimSpace(gotQuery) == "" {
		t.Error("brain hook received an empty query; deriveDiffLessQuery produced nothing")
	}
	if !strings.Contains(out.String(), "diff-less mode (entire-brain)") {
		t.Errorf("expected the diff-less banner in output:\n%s", out.String())
	}
}

package cli

import (
	"strings"
	"testing"
)

func TestFormatDiffLessReview(t *testing.T) {
	section := formatDiffLessReview(diffLessReport{
		Summary: "Diff-less review: 1 suspected regression(s)",
		Findings: []diffLessFinding{{
			Severity:   "high",
			File:       "cmd/entire/cli/review_context.go",
			Line:       412,
			Title:      "Suspected regression: `scopeBaseRef` changed",
			Detail:     "history shows `scopeBaseRef+\"..HEAD\"`; current is `\"master..HEAD\"` — verify intentional (could be a rename).",
			Evidence:   "sessions/branches/x.jsonl:2162",
			Confidence: 0.8,
		}},
	})
	for _, want := range []string{
		"Diff-less review (entire-brain) — 1 suspected regression(s)",
		"[HIGH] Suspected regression: `scopeBaseRef` changed",
		"cmd/entire/cli/review_context.go:412",
		"history shows",
		"evidence: sessions/branches/x.jsonl:2162",
	} {
		if !strings.Contains(section, want) {
			t.Fatalf("section missing %q:\n%s", want, section)
		}
	}
}

func TestFormatDiffLessReviewEmpty(t *testing.T) {
	if got := formatDiffLessReview(diffLessReport{Summary: "none", Findings: nil}); got != "" {
		t.Fatalf("no findings must yield empty section, got %q", got)
	}
}

package investigate

import (
	"context"
	"strings"
	"testing"
)

func TestAugmentAlwaysPromptWithBrain(t *testing.T) {
	ctx := context.Background()
	const section = "Diff-less review (entire-brain) — 1 suspected regression(s)"

	// Nil hook: unchanged (graceful no-op).
	if got := augmentAlwaysPromptWithBrain(ctx, Deps{}, "/repo", "topic", "guardrails"); got != "guardrails" {
		t.Fatalf("nil hook should pass through, got %q", got)
	}

	// Hook returns a section: appended after the existing always-prompt.
	var gotQuery string
	deps := Deps{DiffLessInvestigateContext: func(_ context.Context, _ string, q string) string {
		gotQuery = q
		return section
	}}
	got := augmentAlwaysPromptWithBrain(ctx, deps, "/repo", "fix scopeBaseRef", "guardrails")
	if !strings.Contains(got, "guardrails") || !strings.Contains(got, section) {
		t.Fatalf("expected guardrails + brain section, got %q", got)
	}
	if gotQuery != "fix scopeBaseRef" {
		t.Fatalf("hook should receive the topic as query, got %q", gotQuery)
	}

	// Empty always-prompt: section becomes the whole prompt.
	if got := augmentAlwaysPromptWithBrain(ctx, deps, "/repo", "t", ""); got != section {
		t.Fatalf("empty always-prompt should equal section, got %q", got)
	}

	// Hook returns empty: unchanged.
	empty := Deps{DiffLessInvestigateContext: func(_ context.Context, _ string, _ string) string { return "" }}
	if got := augmentAlwaysPromptWithBrain(ctx, empty, "/repo", "t", "guardrails"); got != "guardrails" {
		t.Fatalf("empty section should pass through, got %q", got)
	}
}

