package cli

import (
	"context"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

// TestDiffLessReviewContextShellsBrain proves the full exec+parse link: a fake
// `entire-brain` on PATH emits a canned reviewReport, and diffLessReviewContext
// shells it, parses the JSON, and renders the section. The graceful no-op when
// the brain is absent is covered by TestDiffLessReviewContextNoBrainOnPath.
func TestDiffLessReviewContextShellsBrain(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("sh stub not portable to windows")
	}
	dir := t.TempDir()
	script := "#!/bin/sh\n" + `cat <<'JSON'
{"mode":"diff-less (brain memory vs current tree)","summary":"Diff-less review: 1 suspected regression(s)","findings":[{"severity":"high","file":"pkg/review_context.go","line":412,"title":"Suspected regression: ` + "`scopeBaseRef`" + ` changed","detail":"history shows X; current Y - verify","evidence":"sessions/s.jsonl:1","confidence":0.8}]}
JSON
`
	if err := os.WriteFile(filepath.Join(dir, diffLessBrainBinary), []byte(script), 0o755); err != nil {
		t.Fatal(err)
