input.script:
export const meta = {
  name: 'hard-history-task-design',
  description: 'Design 3 hard, history-advantaged, leak-free benchmark tasks on entireio/cli',
  phases: [
    { title: 'Mine', detail: 'find decisions in session history whose rationale is invisible in current code' },
    { title: 'Design', detail: 'build + mechanically verify one injection per candidate' },
  ],
}

const CLI = '/Users/suhaan/Documents/Coding/cli-bench'
const BRAIN = '/Users/suhaan/.local/share/entire/plugins/data/brain/repos/gh/entireio/cli'
const SHA = 'af713665091693a8301520159f3b4097a6ec36f9'

const MINE_SCHEMA = {
  type: 'object',
  required: ['candidates'],
  properties: {
    candidates: {
      type: 'array',
      items: {
        type: 'object',
        required: ['area', 'invariant', 'why_history_helps', 'evidence'],
        properties: {
          area: { type: 'string', description: 'package/file area in cli-bench' },
          invariant: { type: 'string', description: 'the subtle behavior an injection would break' },
          why_history_helps: { type: 'string', description: 'why the rationale is in sessions but NOT obvious from current code' },
          evidence: { type: 'string', description: 'which exported session/transcript or commit discusses it (cite filename or commit)' },
          difficulty: { type: 'string', description: 'why a capable agent without history would plausibly fail or fix it wrongly' },
        },
      },
    },
  },
}

const DESIGN_SCHEMA = {
  type: 'object',
  required: ['slug', 'status'],
  properties: {
    slug: { type: 'string' },
    status: { type: 'string', enum: ['verified', 'failed'] },
    reason: { type: 'string' },
    file: { type: 'string' },
    old: { type: 'string', description: 'EXACT file substring, appears exactly once, byte-exact tabs/newlines, extracted programmatically' },
    new: { type: 'string' },
    test_command: { type: 'string', description: 'focused hidden validation that fails with the bug, passes clean, offline, <120s' },
    fail_snippet: { type: 'string' },
    prompt: { type: 'string', description: 'symptom-only; NO file/function/test names, NO fix description' },
    brain_queries: { type: 'array', items: { type: 'string' }, description: 'symptom-level; NO identifier-shaped token that appears in the fix old/new/path, validation, test names, or hidden expected files (check literally, case-insensitively); no 3-word phrase from those' },
    expected_files: { type: 'array', items: { type: 'string' } },
    history_evidence: { type: 'string', description: 'session/transcript file(s) under the brain export that contain the rationale' },
    hardness_argument: { type: 'string', description: 'why no_brain plausibly fails: what wrong-but-plausible fix exists' },
  },
}

phase('Mine')
const LENSES = [
  `Lens A — reverted/changed decisions: search git log of ${CLI} for reverts, "instead", "back out", "rationale" commits, and cross-reference the exported session transcripts under ${BRAIN}/sessions (grep for the same symbols). Find invariants whose WHY lives in a session discussion.`,
  `Lens B — guard clauses + special cases: grep ${CLI} (cmd/, internal/) for non-obvious special-case code (sleep/retry/ordering/escaping/locale special cases) with a focused test, where deleting the special case still LOOKS correct. Then check ${BRAIN}/sessions transcripts for discussions explaining the special case.`,
  `Lens C — cross-file contracts: find pairs of files in ${CLI} where one file's behavior silently depends on another's (state realignment, ref naming, trailer formats). The exported sessions at ${BRAIN}/sessions often discuss these contracts. Avoid areas already used by existing benchmark tasks: manual-commit attribution base realign, transcript re-resolution, review base-flag scope, review prompt uncommitted scope, provenance env filtering, plugin env XDG prefix, external command env filter.`,
]
const mined = await parallel(LENSES.map((lens, i) => () =>
  agent(`You are mining the entireio/cli repo + its exported Entire session history for HARD benchmark task candidates — tasks where an agent WITHOUT session history plausibly fails or fixes wrongly, and the deciding rationale is recoverable from session transcripts.

Repo: ${CLI} at ${SHA} (read-only — do NOT modify).
Exported session transcripts + history index: ${BRAIN} (look in sessions/ and history/ subdirs; transcripts are raw .jsonl — grep them, do not read whole files).

${lens}

Return 2-4 candidates via structured output. Quality bar: the invariant must have a REAL focused test (or a hidden test must be writable from existing test helpers), the wrong-but-plausible alternative fix must be concrete, and the session evidence must be a real file you found (cite it).`, { label: `mine:${i}`, phase: 'Mine', schema: MINE_SCHEMA })
))

const candidates = mined.filter(Boolean).flatMap((m) => m.candidates).slice(0, 8)
log(`mined ${candidates.length} candidates`)

phase('Design')
const designs = await parallel(candidates.slice(0, 6).map((c, i) => () =>
  agent(`Design ONE hard, history-advantaged, leak-free benchmark task from this mined candidate:

AREA: ${c.area}
INVARIANT: ${c.invariant}
WHY HISTORY HELPS: ${c.why_history_helps}
SESSION EVIDENCE: ${c.evidence}
DIFFICULTY ARGUMENT: ${c.difficulty}

Repo: ${CLI} pinned at ${SHA}. NEVER edit the main clone — create an isolated worktree:
  git -C ${CLI} worktree add --detach /tmp/clibench-wt-${i} ${SHA}
Work there; remove it when done: git -C ${CLI} worktree remove --force /tmp/clibench-wt-${i}

Requirements:
1. Injection in a PRODUCTION .go file: remove/invert the subtle invariant so the code still compiles and LOOKS plausible. 'old' must appear EXACTLY ONCE (verify with python count==1, extract byte-exact programmatically).
2. Hidden validation: a focused go test command that FAILS with the bug and PASSES clean (verify mechanically: clean PASS -> apply -> FAIL -> build OK -> revert -> PASS). Offline, <120s.
3. HARDNESS: there must be a wrong-but-plausible fix a no-history agent would write (state it). If the obvious grep leads straight to the right fix, REJECT (status=failed, reason).
4. NO LEAKS: prompt is symptom-only (observable CLI/tool behavior); brain_queries are symptom-level with NO identifier-shaped token that appears (case-insensitively) in the old/new text, the file path, validation commands, test names, or expected files — and no 3-word phrase from any of those. Check every token literally before returning.
5. history_evidence: cite the actual session transcript file(s) under ${BRAIN} containing the rationale.

Return structured output only.`, { label: `design:${i}`, phase: 'Design', schema: DESIGN_SCHEMA })
))

const verified = designs.filter(Boolean).filter((d) => d.status === 'verified')
log(`verified hard-history candidates: ${verified.length}`)
return { verified, failed: designs.filter(Boolean).filter((d) => d.status === 'failed'), minedCount: candidates.length }

