  description: 'High-recall code review of the history-delivery-fix branch diff (7 angles + verify)',
  phases: [
    { title: 'Find', detail: '7 independent finder angles over the diff' },
    { title: 'Verify', detail: '1-vote recall-biased verification of each candidate' },
  ],
}

const WT = '/Users/suhaan/Documents/Coding/entire-brain-histfix'
const BASE = 'origin/main'

const CAND_SCHEMA = {
  type: 'object', required: ['candidates'],
  properties: { candidates: { type: 'array', items: {
    type: 'object', required: ['file','line','summary','failure_scenario'],
    properties: { file: {type:'string'}, line: {type:['integer','string']}, summary: {type:'string'}, failure_scenario: {type:'string'} } } } },
}
const VERDICT_SCHEMA = {
  type: 'object', required: ['verdict','reason'],
  properties: { verdict: {type:'string', enum:['CONFIRMED','PLAUSIBLE','REFUTED']}, reason: {type:'string'} },
}

const DIFF = `Review scope: \`git -C ${WT} diff ${BASE}...HEAD\` — the history-delivery-fix branch. Touched code is benchmarks/agent-brain/run.py (prompt_for full_cli_compact policy rewrite; brain_prep_commands export->refresh sessions; new capture_brief_packet + its run_one call site) and benchmarks/agent-brain/run_test.py (new/updated tests). Also evidence/history-delivery-fix/*.md (claims). Read the diff AND the enclosing functions in run.py. Return up to 6 candidates with file/line/summary/concrete failure_scenario.`

const ANGLES = [
  { key:'line-scan', p:`${DIFF}\n\nANGLE A — line-by-line: read every changed hunk + its enclosing function. Hunt inverted/wrong conditions, off-by-one, None/KeyError, falsy-zero, wrong-variable copy-paste, swallowed exceptions, unescaped regex, f-string placeholder errors, the str(condition).startswith("mcp") / agent_runs_cli_brief logic, the --limit gating, the brief_query reconstruction vs prompt_for.` },
  { key:'removed-behavior', p:`${DIFF}\n\nANGLE B — removed-behavior: for every DELETED/replaced line (old full_cli_compact policy "do not broaden"/"Treat the packet as sufficient"; old export command; old test assertions), name the invariant it enforced and find where the new code re-establishes it or why it's safe to drop. Flag any dropped guard.` },
  { key:'cross-file', p:`${DIFF}\n\nANGLE C — cross-file: capture_brief_packet is called in run_one; check arg order (task,condition,runner,worktree,env,tools,run_dir) matches the def, that run_dir vs worktree is correct, that it's after post-brain setup, and that prompt_for's brief command EXACTLY equals what capture_brief_packet reconstructs for every condition. Check brain_prep_commands callers expect the new command shape.` },
  { key:'reuse', p:`${DIFF}\n\nREUSE angle: does capture_brief_packet re-implement brief-query/limit logic that prompt_for already has (drift risk)? Should it share a helper? Name it.` },
  { key:'simplify', p:`${DIFF}\n\nSIMPLIFICATION angle: redundant/derivable state, copy-paste, dead code in the new code. Name the simpler form.` },
  { key:'efficiency', p:`${DIFF}\n\nEFFICIENCY angle: capture_brief_packet runs an extra \`entire brain brief\` subprocess per non-no_brain run (timeout 180s) purely for a diagnostic file — flag the added cost/wall-time on every benchmark run; any other wasted work.` },
  { key:'altitude', p:`${DIFF}\n\nALTITUDE angle: is the fix at the right depth? The full_cli_compact policy is rewritten per-branch (opus + generic) with near-duplicate text; the real defect (brief likely_edit_files lexical false positives) lives in the Go brief ranking. Is the prompt-policy fix a bandaid vs fixing ranking? Is capture_brief_packet's condition logic duplicating prompt_for's branch logic (two places to keep in sync)?` },
]

phase('Find')
const found = await parallel(ANGLES.map(a => () => agent(a.p, { label:`find:${a.key}`, phase:'Find', schema: CAND_SCHEMA })))
const cands = found.filter(Boolean).flatMap(r => r.candidates || [])
// dedup by file+summary-ish
const seen = new Set(); const uniq = []
for (const c of cands) { const k = `${c.file}:${String(c.summary).slice(0,40).toLowerCase()}`; if (!seen.has(k)) { seen.add(k); uniq.push(c) } }
log(`candidates: ${cands.length}, deduped: ${uniq.length}`)

phase('Verify')
const verified = await parallel(uniq.map(c => () =>
  agent(`Verify this code-review candidate against the actual code in ${WT} (diff vs ${BASE}). Return CONFIRMED (constructible real defect), PLAUSIBLE (realistic state triggers it), or REFUTED (factually wrong/impossible/already-handled/pure-style-no-effect — cite the line). Recall-biased: PLAUSIBLE by default for realistic edge cases. Candidate: [${c.file}:${c.line}] ${c.summary} — ${c.failure_scenario}`,
    { label:`verify`, phase:'Verify', schema: VERDICT_SCHEMA })
    .then(v => ({ ...c, ...v }))))
const kept = verified.filter(Boolean).filter(x => x.verdict !== 'REFUTED')
log(`kept (CONFIRMED+PLAUSIBLE): ${kept.length}`)
return { findings: kept.slice(0, 10) }

