261	// stripJSONFences removes a leading/embedded ```json fence wrapper so the object
262	// extractor sees bare JSON. It is tolerant: content without fences is returned
263	// unchanged.
264	func stripJSONFences(s string) string {
265		s = strings.TrimSpace(s)
266		if !strings.Contains(s, "```") {
267			return s
268		}
269		if idx := strings.Index(s, "```"); idx >= 0 {
270			rest := s[idx+3:]
271			if nl := strings.IndexByte(rest, '\n'); nl >= 0 {
272				lang := strings.TrimSpace(rest[:nl])
273				if lang == "json" || lang == "" || !strings.Contains(lang, "{") {
274					rest = rest[nl+1:]
275				}
276			}
277			if closeIdx := strings.Index(rest, "```"); closeIdx >= 0 {
278				rest = rest[:closeIdx]
279			}
280			return strings.TrimSpace(rest)
281		}
282		return s
283	}
