285	// extractOuterJSONObject returns the substring from the first '{' to its matching
286	// '}', tracking string literals so a brace inside a JSON string does not throw
287	// off the balance. ok=false when no balanced object is present.
288	func extractOuterJSONObject(s string) (string, bool) {
289		start := strings.IndexByte(s, '{')
290		if start < 0 {
291			return "", false
292		}
293		depth := 0
294		inString := false
295		escaped := false
296		for i := start; i < len(s); i++ {
297			c := s[i]
298			if inString {
299				switch {
300				case escaped:
301					escaped = false
302				case c == '\\':
303					escaped = true
304				case c == '"':
305					inString = false
306				}
307				continue
308			}
309			switch c {
310			case '"':
311				inString = true
312			case '{':
313				depth++
314			case '}':
315				depth--
316				if depth == 0 {
317					return s[start : i+1], true
318				}
319			}
320		}
321		return "", false
322	}
