383	func anchorResolves(anchor string, sessionIDs, commitHashes map[string]struct{}) bool {
384		lower := strings.ToLower(anchor)
385		if _, ok := sessionIDs[strings.TrimSpace(lower)]; ok {
386			return true
387		}
388		for _, tok := range strings.FieldsFunc(lower, func(r rune) bool {
389			return !(r >= 'a' && r <= 'z' || r >= '0' && r <= '9')
390		}) {
