406	// "agent×count" slice, most-used first then alphabetical.
407	func sortedAgentHistogram(histogram map[string]int) []string {
408		type pair struct {
409			agent string
410			count int
411		}
412		pairs := make([]pair, 0, len(histogram))
413		for a, c := range histogram {
414			pairs = append(pairs, pair{a, c})
415		}
416		sort.Slice(pairs, func(i, j int) bool {
417			if pairs[i].count != pairs[j].count {
418				return pairs[i].count > pairs[j].count
419			}
420			return pairs[i].agent < pairs[j].agent
421		})
422		out := make([]string, 0, len(pairs))
423		for _, p := range pairs {
424			out = append(out, fmt.Sprintf("%s×%d", p.agent, p.count))
425		}
426		return out
427	}
