431	func truncateString(value string, max int) string {
432		if max <= 0 {
433			return ""
434		}
435		if len(value) <= max {
436			return value
437		}
438		limit := max
439		suffix := ""
440		if max > 3 {
441			limit = max - 3
442			suffix = "..."
443		}
444		cut := limit
445		for cut > 0 && !utf8RuneStart(value[cut]) {
446			cut--
447		}
448		return value[:cut] + suffix
449	}
