package tui

import (
	"fmt"

	"github.com/charmbracelet/bubbles/table"
	"github.com/charmbracelet/lipgloss"

	"github.com/suhaanthayyil/entire-judge/internal/judge"
)

const (
	sectionRanked = iota
	sectionExcluded
)

// newSubmissionTable builds the left-pane table, themed and focused.
func newSubmissionTable(th Theme) table.Model {
	t := table.New(table.WithFocused(true))
	s := table.DefaultStyles()
	s.Header = s.Header.
		Foreground(th.Dim).
		BorderStyle(lipgloss.NormalBorder()).
		BorderForeground(th.Border).
		BorderBottom(true).
		Bold(false)
	s.Selected = s.Selected.
		Foreground(lipgloss.Color("0")).
		Background(th.Accent).
		Bold(true)
	s.Cell = s.Cell.Foreground(th.Text)
	t.SetStyles(s)
	return t
}

// submissionColumns lays out the columns for a given inner table width: a rank
// number, a flexible submission id, a fixed score, and a one-glyph flag marker.
func submissionColumns(innerWidth int) []table.Column {
	const rankW, scoreW, flagW = 3, 5, 2
	idW := innerWidth - rankW - scoreW - flagW - 4 // account for cell padding
	if idW < 10 {
		idW = 10
	}
	return []table.Column{
		{Title: "#", Width: rankW},
		{Title: "Submission", Width: idW},
		{Title: "Score", Width: scoreW},
		{Title: "⚑", Width: flagW},
	}
}

// submissionRows renders the reports for a section into table rows. The ranked
// section shows the rank and composite; the excluded section shows a dash and a
// "gate" marker since hard-gated submissions are not composited.
func submissionRows(reports []judge.RunReport, section int) []table.Row {
	rows := make([]table.Row, 0, len(reports))
	for i := range reports {
		r := reports[i]
		rank := "—"
		score := "—"
		if section == sectionRanked {
			rank = fmt.Sprintf("%d", i+1)
			if r.Composite != nil {
				score = fmt.Sprintf("%.2f", *r.Composite)
			}
		} else {
			score = "gate"
		}
		flag := " "
		if len(r.Flags) > 0 {
			flag = "⚑"
		}
		rows = append(rows, table.Row{rank, r.SubmissionID, score, flag})
	}
	return rows
}

package tui

import (
	"fmt"
	"sort"
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/suhaanthayyil/entire-judge/internal/judge"
)

// lensWeights are the composite weights, for display next to each scored lens.
var lensWeights = map[string]string{
	judge.LensAuthenticity: "30%",
	judge.LensOutcome:      "30%",
	judge.LensPrompting:    "20%",
	judge.LensEffort:       "20%",
}

// renderDetail renders one submission's page: Header, Score, Summary, Findings.
// width is the content width inside the detail viewport.
func renderDetail(th Theme, r *judge.RunReport, meta judge.RunMetadata, excluded bool, width int) string {
	if width < 20 {
		width = 20
	}
	wrap := lipgloss.NewStyle().Width(width)
	var b strings.Builder

	// ---- Header ----
	b.WriteString(th.titleStyle().Render(r.SubmissionID))
	b.WriteString("\n")
	b.WriteString(th.dimStyle().Render(truncate(r.RepoDir, width)))
	b.WriteString("\n")
	meta1 := fmt.Sprintf("agent %s", meta.Agent)
	if meta.Model != "" {
		meta1 += " (" + meta.Model + ")"
	}
	meta1 += " · LLM " + r.Run.LLMStatus
	if r.Run.HackathonStartedAt != nil {
		meta1 += " · start " + r.Run.HackathonStartedAt.Format("2006-01-02 15:04Z")
	}
	b.WriteString(th.dimStyle().Render(truncate(meta1, width)))
	b.WriteString("\n\n")

	if excluded {
		reason := judge.HardGateReason(r.Deterministic.TimelineCategory)
		if reason == "" {
			reason = "held out of the ranking"
		}
		b.WriteString(lipgloss.NewStyle().Foreground(th.Bad).Bold(true).Render("EXCLUDED — hard gate"))
		b.WriteString("\n")
		b.WriteString(wrap.Render(th.dimStyle().Render(reason)))
		b.WriteString("\n\n")
	} else {
		composite := "n/a"
		var color = th.Dim
		if r.Composite != nil {
			composite = fmt.Sprintf("%.2f / 5", *r.Composite)
			color = th.scoreColor(*r.Composite)
		}
		b.WriteString(lipgloss.NewStyle().Foreground(color).Bold(true).Render("Composite  "+composite))
		b.WriteString("\n\n")
	}

	// ---- Score ----
	b.WriteString(sectionHeader(th, "Score"))
	b.WriteString("\n")
	for i := range r.Lenses {
		lens := r.Lenses[i]
		label := lens.Lens
		if w, ok := lensWeights[lens.Lens]; ok {
			label += "  " + th.dimStyle().Render("("+w+")")
		}
		if lens.Score != nil {
			b.WriteString("  " + coloredScoreBar(th, lens.Score) + "  " + label + "\n")
		} else {
			// descriptive (agent_leverage)
			desc := lens.Verdict
			if desc == "" {
				desc = "—"
			}
			b.WriteString("  " + th.dimStyle().Render("·····") + "       " + lens.Lens + ": " + th.dimStyle().Render(desc) + "\n")
		}
	}
	if len(r.Flags) > 0 {
		b.WriteString("  " + th.flagStyle().Render("flags: "+strings.Join(r.Flags, ", ")) + "\n")
	}
	b.WriteString("\n")

	// ---- Summary ----
	b.WriteString(sectionHeader(th, "Summary"))
	b.WriteString("\n")
	b.WriteString(wrap.Render(th.textStyle().Render(judge.SummaryText(r))))
	b.WriteString("\n\n")

	// ---- Findings ----
	b.WriteString(sectionHeader(th, "Findings"))
	b.WriteString("\n")
	b.WriteString(findingsBlock(th, r, width))

	return b.String()
}

// findingsBlock renders the deterministic metrics, then each lens's verdict,
// bullets, and evidence anchors, then any warnings.
func findingsBlock(th Theme, r *judge.RunReport, width int) string {
	wrap := lipgloss.NewStyle().Width(width)
	m := r.Deterministic
	var b strings.Builder

	metric := func(label, value string) {
		b.WriteString("  " + th.dimStyle().Render(label+": ") + value + "\n")
	}
	metric("timeline", fmt.Sprintf("%s (%s)", m.TimelineCategory, m.TimelineReason))
	metric("activity", fmt.Sprintf("%d sessions · %d turns · %d human prompts · %d files · %d facts",
		m.Sessions, m.Turns, m.HumanPrompts, m.FilesTouched, m.Facts))
	metric("effort", fmt.Sprintf("%s on task · %d in / %d out tokens",
		humanMinutes(m.TimeOnTaskMinutes), m.InputTokens, m.OutputTokens))
	metric("commits", fmt.Sprintf("%d total · %d pre-session · %d covered · %d missing-session",
		m.TotalCommits, m.PreSessionCommits, m.CoveredCommits, m.MissingSessionCommits))
	if m.FirstCommitAt != nil && m.FirstSessionAt != nil {
		rel := "after"
		if m.FirstCommitBeforeFirstSess {
			rel = "before"
		}
		metric("first commit", fmt.Sprintf("%.0f min %s first session", absFloat(m.FirstCommitToFirstSession), rel))
	}
	if agents := agentMix(m); agents != "" {
		metric("agents", agents)
	}
	b.WriteString("\n")

	for i := range r.Lenses {
		lens := r.Lenses[i]
		if lens.Verdict == "" && len(lens.Bullets) == 0 && len(lens.Evidence) == 0 {
			continue
		}
		b.WriteString("  " + th.titleStyle().Render(lens.Lens) + "\n")
		if lens.Verdict != "" {
			b.WriteString(wrap.Render("    " + th.textStyle().Render(lens.Verdict)))
			b.WriteString("\n")
		}
		for _, bullet := range lens.Bullets {
			b.WriteString(wrap.Render("    • " + bullet))
			b.WriteString("\n")
		}
		for _, e := range lens.Evidence {
			b.WriteString("    " + th.dimStyle().Render("↳ "+truncate(e, width-6)) + "\n")
		}
		if !lens.Supported && lens.Score != nil {
			b.WriteString("    " + th.flagStyle().Render("(unsupported: no evidence anchor resolved)") + "\n")
		}
		b.WriteString("\n")
	}

	for _, w := range r.Warnings {
		b.WriteString("  " + th.flagStyle().Render("⚠ "+w) + "\n")
	}
	return b.String()
}

func sectionHeader(th Theme, title string) string {
	return th.titleStyle().Render("▌ " + title)
}

// coloredScoreBar renders a themed "█████ 4.5" bar colored by the score band.
func coloredScoreBar(th Theme, score *float64) string {
	const cells = 5
	if score == nil {
		return th.dimStyle().Render(strings.Repeat("░", cells) + "  -")
	}
	filled := int(*score + 0.5)
	if filled < 0 {
		filled = 0
	}
	if filled > cells {
		filled = cells
	}
	bar := strings.Repeat("█", filled) + strings.Repeat("░", cells-filled)
	styled := lipgloss.NewStyle().Foreground(th.scoreColor(*score)).Render(bar)
	return styled + fmt.Sprintf("  %.1f", *score)
}

// agentMix renders the agent histogram as "Codex×14, Claude Code×3", most-used
// first then alphabetical, with the primary agent leading implicitly.
func agentMix(m judge.Metrics) string {
	if len(m.AgentHistogram) == 0 {
		return m.PrimaryAgent
	}
	type pair struct {
		agent string
		count int
	}
	pairs := make([]pair, 0, len(m.AgentHistogram))
	for a, c := range m.AgentHistogram {
		pairs = append(pairs, pair{a, c})
	}
	sort.Slice(pairs, func(i, j int) bool {
		if pairs[i].count != pairs[j].count {
			return pairs[i].count > pairs[j].count
		}
		return pairs[i].agent < pairs[j].agent
	})
	parts := make([]string, 0, len(pairs))
	for _, p := range pairs {
		parts = append(parts, fmt.Sprintf("%s×%d", p.agent, p.count))
	}
	return strings.Join(parts, ", ")
}

func humanMinutes(mins float64) string {
	if mins < 90 {
		return fmt.Sprintf("%.0f min", mins)
	}
	return fmt.Sprintf("%.1f h", mins/60)
}

func absFloat(f float64) float64 {
	if f < 0 {
		return -f
	}
	return f
}

// Package tui renders the interactive jury dashboard for entire-judge: a ranked
// submission table on the left and a per-submission page (Score / Summary /
// Findings) on the right, with vim+arrow navigation, section tabs, a fuzzy
// filter, a help bar, and selectable themes. On a non-TTY the caller falls back
// to the rendered text summary, so the TUI is only constructed for a real
// terminal.
package tui

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/bubbles/help"
	"github.com/charmbracelet/bubbles/key"
	"github.com/charmbracelet/bubbles/table"
	"github.com/charmbracelet/bubbles/textinput"
	"github.com/charmbracelet/bubbles/viewport"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"

	"github.com/suhaanthayyil/entire-judge/internal/judge"
)

// Model is the dashboard model over a ranked + excluded set of submissions.
type Model struct {
	ranked   []judge.RunReport
	excluded []judge.RunReport
	meta     judge.RunMetadata
	theme    Theme

	keys   keyMap
	help   help.Model
	table  table.Model
	vp     viewport.Model
	filter textinput.Model

	section     int // sectionRanked | sectionExcluded
	visible     []judge.RunReport
	focusDetail bool
	filtering   bool

	width, height int
	leftInner     int
	rightInner    int
	paneContentH  int
	detailWidth   int
	ready         bool
}

// NewModel builds a dashboard over the ranked and excluded submissions.
func NewModel(ranked, excluded []judge.RunReport, theme Theme, meta judge.RunMetadata) Model {
	ti := textinput.New()
	ti.Prompt = "filter: "
	ti.CharLimit = 64

	m := Model{
		ranked:   ranked,
		excluded: excluded,
		meta:     meta,
		theme:    theme,
		keys:     defaultKeys(),
		help:     help.New(),
		table:    newSubmissionTable(theme),
		vp:       viewport.New(60, 20),
		filter:   ti,
		width:    100,
		height:   30,
		section:  sectionRanked,
	}
	m.rebuildVisible()
	return m
}

func (m Model) Init() tea.Cmd { return nil }

func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.ready = true
		m.resize()
		return m, nil
	case tea.KeyMsg:
		if msg.Type == tea.KeyCtrlC {
			return m, tea.Quit
		}
		if m.filtering {
			return m.updateFiltering(msg)
		}
		switch {
		case key.Matches(msg, m.keys.Quit):
			return m, tea.Quit
		case key.Matches(msg, m.keys.Help):
			m.help.ShowAll = !m.help.ShowAll
			m.resize()
			return m, nil
		case key.Matches(msg, m.keys.Filter):
			m.filtering = true
			m.filter.Focus()
			return m, textinput.Blink
		case key.Matches(msg, m.keys.Section):
			m.section = sectionRanked + sectionExcluded - m.section
			m.focusDetail = false
			m.table.SetCursor(0)
			m.rebuildVisible()
			return m, nil
		}
		if m.focusDetail {
			if key.Matches(msg, m.keys.Back) {
				m.focusDetail = false
				return m, nil
			}
			var cmd tea.Cmd
			m.vp, cmd = m.vp.Update(msg)
			return m, cmd
		}
		// list focus
		if key.Matches(msg, m.keys.Enter) {
			if len(m.visible) > 0 {
				m.focusDetail = true
			}
			return m, nil
		}
		prev := m.table.Cursor()
		var cmd tea.Cmd
		m.table, cmd = m.table.Update(msg)
		if m.table.Cursor() != prev {
			m.refreshDetail()
		}
		return m, cmd
	}
	return m, nil
}

func (m Model) updateFiltering(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "esc":
		m.filtering = false
		m.filter.Blur()
		m.filter.SetValue("")
		m.rebuildVisible()
		return m, nil
	case "enter":
		m.filtering = false
		m.filter.Blur()
		return m, nil
	}
	var cmd tea.Cmd
	m.filter, cmd = m.filter.Update(msg)
	m.rebuildVisible()
	return m, cmd
}

// resize recomputes the pane geometry from the terminal size and re-flows the
// table, viewport, and detail content.
func (m *Model) resize() {
	leftTotal := m.width / 3
	if leftTotal < 30 {
		leftTotal = 30
	}
	if leftTotal > 52 {
		leftTotal = 52
	}
	rightTotal := m.width - leftTotal
	m.leftInner = max(leftTotal-2, 12)
	m.rightInner = max(rightTotal-2, 20)

	footerH := 2
	if m.help.ShowAll {
		footerH = 4
	}
	bodyTotalH := m.height - 2 /*header*/ - footerH
	if bodyTotalH < 8 {
		bodyTotalH = 8
	}
	m.paneContentH = bodyTotalH - 2 // pane borders

	m.table.SetColumns(submissionColumns(m.leftInner))
	m.table.SetWidth(m.leftInner)
	m.table.SetHeight(max(m.paneContentH-1, 3))

	m.vp.Width = m.rightInner
	m.vp.Height = m.paneContentH
	m.help.Width = m.width
	m.filter.Width = m.leftInner - len(m.filter.Prompt) - 1
	m.detailWidth = m.rightInner
	m.refreshDetail()
}

func (m *Model) source() []judge.RunReport {
	if m.section == sectionExcluded {
		return m.excluded
	}
	return m.ranked
}

// rebuildVisible recomputes the filtered rows for the active section and refreshes
// the table + detail.
func (m *Model) rebuildVisible() {
	q := strings.ToLower(strings.TrimSpace(m.filter.Value()))
	m.visible = m.visible[:0]
	for _, r := range m.source() {
		if q == "" || strings.Contains(strings.ToLower(r.SubmissionID), q) {
			m.visible = append(m.visible, r)
		}
	}
	m.table.SetRows(submissionRows(m.visible, m.section))
	if m.table.Cursor() >= len(m.visible) {
		m.table.SetCursor(max(0, len(m.visible)-1))
	}
	m.refreshDetail()
}

func (m *Model) refreshDetail() {
	if len(m.visible) == 0 {
		m.vp.SetContent(m.theme.dimStyle().Render("No submissions in this section."))
		m.vp.GotoTop()
		return
	}
	idx := m.table.Cursor()
	if idx < 0 || idx >= len(m.visible) {
		idx = 0
	}
	content := renderDetail(m.theme, &m.visible[idx], m.meta, m.section == sectionExcluded, m.detailWidth)
	m.vp.SetContent(content)
	m.vp.GotoTop()
}

func (m Model) View() string {
	if !m.ready {
		return "loading…"
	}
	if len(m.ranked) == 0 && len(m.excluded) == 0 {
		return "No submissions to display.\n"
	}

	// ---- header + tabs/filter ----
	title := m.theme.titleStyle().Render("entire-judge") +
		m.theme.dimStyle().Render(fmt.Sprintf("  ·  %d ranked · %d excluded  ·  agent %s",
			len(m.ranked), len(m.excluded), m.meta.Agent))

	var secondRow string
	if m.filtering {
		secondRow = m.filter.View()
	} else {
		secondRow = m.renderTabs()
	}

	// ---- body panes ----
	leftPane := m.theme.paneStyle(!m.focusDetail).
		Width(m.leftInner).Height(m.paneContentH).Render(m.table.View())
	rightPane := m.theme.paneStyle(m.focusDetail).
		Width(m.rightInner).Height(m.paneContentH).Render(m.vp.View())
	body := lipgloss.JoinHorizontal(lipgloss.Top, leftPane, rightPane)

	// ---- footer ----
	footer := m.help.View(m.keys) + "\n" +
		lipgloss.NewStyle().Foreground(m.theme.Dim).Italic(true).Render(judge.Disclaimer)

	return strings.Join([]string{title, secondRow, body, footer}, "\n")
}

func (m Model) renderTabs() string {
	active := lipgloss.NewStyle().Background(m.theme.Accent).Foreground(lipgloss.Color("0")).Bold(true)
	inactive := m.theme.dimStyle()
	ranked := fmt.Sprintf(" Ranked (%d) ", len(m.ranked))
	excluded := fmt.Sprintf(" Excluded (%d) ", len(m.excluded))
	if m.section == sectionRanked {
		return active.Render(ranked) + " " + inactive.Render(excluded)
	}
	return inactive.Render(ranked) + " " + active.Render(excluded)
}

// ScoreBar renders a score as a "█████░░ 4.0/5" style bar; an unscored lens shows
// a dash bar. It is plain text (no ANSI) so the non-TTY plain renderer can reuse
// it; the TUI uses its own colored bar.
func ScoreBar(score *float64) string {
	const cells = 5
	if score == nil {
		return strings.Repeat("░", cells) + " -/5"
	}
	filled := int(*score + 0.5)
	if filled < 0 {
		filled = 0
	}
	if filled > cells {
		filled = cells
	}
	return strings.Repeat("█", filled) + strings.Repeat("░", cells-filled) + fmt.Sprintf(" %.1f/5", *score)
}

func truncate(value string, max int) string {
	if max <= 0 {
		return ""
	}
	if len(value) <= max {
		return value
	}
	if max <= 3 {
		return value[:max]
	}
	return value[:max-3] + "..."
}

