export const meta = {
  name: 'entire-judge-review',
  description: 'Adversarial multi-dimension review of the entire-judge feature diff, with each finding independently verified',
  phases: [
    { title: 'Review', detail: 'one reviewer per dimension over the diff' },
    { title: 'Verify', detail: 'adversarially confirm each finding is real' },
  ],
}

const REPO = '/Users/suhaan/Documents/Coding/entire-judge'
const DIFF = `git -C ${REPO} diff origin/main..HEAD`

const FINDINGS = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          severity: { type: 'string', enum: ['critical', 'major', 'minor'] },
          file: { type: 'string' },
          location: { type: 'string', description: 'function or line context' },
          issue: { type: 'string' },
          evidence: { type: 'string', description: 'concrete code citation' },
          fix: { type: 'string' },
        },
        required: ['severity', 'file', 'issue', 'evidence'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT = {
  type: 'object',
  properties: {
    real: { type: 'boolean' },
    severity: { type: 'string', enum: ['critical', 'major', 'minor'] },
    reasoning: { type: 'string' },
  },
  required: ['real', 'reasoning'],
}

const DIMENSIONS = [
  { key: 'correctness', focus: 'Logic bugs in the new Go code: judge add (URL→dirname parsing for https/scp/.git/trailing-slash, clone/fetch flow, brain-build env), the sem snapshot reader (NDJSON parse, header-line skipping, path-traversal guard, symbol/relation/file counting, fallback to source counts), the LLM summary (lenient JSON parse, empty→fallback), and any off-by-one or nil-deref.' },
  { key: 'tui-rendering', focus: 'TUI correctness and rendering: pane sizing math (dynamic footer height, title/tabs clipping), the mouse click→row hit-test offset (title/tabs/border/header = 4), OSC 8 link zero-width handling, medal emoji column width, focus model (list vs detail), empty-section and single-submission and narrow-terminal edge cases, and any path that could panic in Update/View.' },
  { key: 'security-egress', focus: 'Security and no-egress: does any new path send brain context off-host without the no-egress gate? Is the sem snapshot path-traversal guard sufficient (abs paths, .. segments, symlinks)? Does `add` shell out safely (no injection via repo URL into exec)? Does the summary lens honor RejectForNoEgress like the other lenses?' },
  { key: 'schema-compat', focus: 'Schema and backward-compatibility: the new RunReport.Summary field, RankExcluded.Report field, and Metrics semantic_* fields — are they additive and omitempty-safe for existing JSON consumers? Does openSavedBoard correctly reconstruct ranked+excluded from a saved board, and reject non-board JSON? Does the composite math still exclude unsupported lenses?' },
  { key: 'tests-gaps', focus: 'Test coverage gaps and correctness of the new tests: are there untested branches (judge add build path, sem absent vs present in the lens brief, summary fallback wiring in Submit, saved-board load)? Do any tests assert the wrong thing or pass vacuously?' },
]

phase('Review')
const results = await pipeline(
  DIMENSIONS,
  (d) => agent(
    `You are reviewing an uncommitted feature branch of the entire-judge Go plugin (a hackathon-jury tool). The full change is the diff from:\n\n  ${DIFF}\n\nRun that diff, and Read the changed files in ${REPO} as needed (internal/cli/add.go, internal/brainstore/semantic.go, internal/judge/{lens,summary,submission,model}.go, internal/tui/*.go, internal/cli/commands.go). Build/run is available: \`cd ${REPO} && go vet ./... && go test ./...\` already pass, so focus on real defects the compiler and existing tests do NOT catch.\n\nReview dimension: ${d.key}.\nFocus: ${d.focus}\n\nReport only concrete, real issues with a specific code citation (file + function/line). Do not report style nits or speculative concerns. If the code is correct on this dimension, return an empty findings array.`,
    { label: `review:${d.key}`, phase: 'Review', schema: FINDINGS }
  ).then((r) => ({ dim: d.key, findings: (r && r.findings) || [] })),
  (review) => parallel(
    review.findings.map((f) => () =>
      agent(
        `Adversarially verify this code-review finding against the actual entire-judge source at ${REPO}. Your job is to REFUTE it if you can — default to real=false unless the evidence clearly holds up when you read the cited code.\n\nDimension: ${review.dim}\nSeverity claimed: ${f.severity}\nFile: ${f.file}\nLocation: ${f.location || '(unspecified)'}\nIssue: ${f.issue}\nEvidence cited: ${f.evidence}\nProposed fix: ${f.fix || '(none)'}\n\nRead the cited file/function. Confirm whether the issue is genuinely present and would actually cause a bug, security hole, or wrong result (not a theoretical or already-handled case). Set real=true only if it truly holds.`,
        { label: `verify:${f.file}`, phase: 'Verify', schema: VERDICT }
      ).then((v) => ({ ...f, dim: review.dim, verdict: v }))
    )
  )
)

const confirmed = results
  .flat()
  .filter(Boolean)
  .filter((f) => f.verdict && f.verdict.real)
  .sort((a, b) => {
    const order = { critical: 0, major: 1, minor: 2 }
    return (order[a.verdict.severity || a.severity] ?? 3) - (order[b.verdict.severity || b.severity] ?? 3)
  })

log(`confirmed ${confirmed.length} real finding(s) after adversarial verification`)
return {
  confirmed: confirmed.map((f) => ({
    severity: f.verdict.severity || f.severity,
    dim: f.dim,
    file: f.file,
    location: f.location,
    issue: f.issue,
    evidence: f.evidence,
    fix: f.fix,
    why_real: f.verdict.reasoning,
  })),
}

