363	// runTUI launches the interactive submission browser. On a non-TTY it falls back
364	// to the rendered text summary so the command is never silently inert.
365	func runTUI(cmd *cobra.Command, ranked, excluded []judge.RunReport, theme tui.Theme, meta judge.RunMetadata) error {
366		if !commandOutputIsTTY(cmd) {
367			return fallbackText(cmd, ranked, excluded)
368		}
369		model := tui.NewModel(ranked, excluded, theme, meta)
370		program := tea.NewProgram(model, tea.WithAltScreen(), tea.WithMouseCellMotion(), tea.WithOutput(cmd.OutOrStdout()))
371		_, err := program.Run()
372		return err
373	}
374	
375	func fallbackText(cmd *cobra.Command, ranked, excluded []judge.RunReport) error {
376		all := append(append([]judge.RunReport(nil), ranked...), excluded...)
377		if len(all) == 1 {
378			printRunReport(cmd, &all[0])
379			return nil
380		}
381		for i := range all {
382			printRunReport(cmd, &all[i])
383			fmt.Fprintln(cmd.OutOrStdout(), strings.Repeat("-", 60))
384		}
385		return nil
386	}
