388	// openSavedBoard loads a previously saved ranking (`rank --json > board.json`)
389	// and opens the dashboard from it directly, with no re-scoring. It accepts a
390	// saved ranking or a single saved submission report.
391	func openSavedBoard(cmd *cobra.Command, flags runFlags, path string) error {
392		data, err := os.ReadFile(path)
393		if err != nil {
394			return fmt.Errorf("read_saved_board: %w", err)
395		}
396	
397		var rank judge.RankReport
398		if err := json.Unmarshal(data, &rank); err == nil && rank.Kind == "entire_judge_ranking" {
399			var ranked, excluded []judge.RunReport
400			for _, e := range rank.Submissions {
401				if e.Report != nil {
402					ranked = append(ranked, *e.Report)
403				}
404			}
405			for _, e := range rank.Excluded {
406				if e.Report != nil {
407					excluded = append(excluded, *e.Report)
408				}
409			}
410			if len(ranked) == 0 && len(excluded) == 0 {
411				return fmt.Errorf("saved_board_empty: %s has no embedded submission reports (re-run `rank --json` to regenerate)", path)
412			}
413			return runTUI(cmd, ranked, excluded, resolveTheme(flags.theme), rank.Run)
414		}
415	
416		var single judge.RunReport
417		if err := json.Unmarshal(data, &single); err == nil && single.Kind == "entire_judge_submission" {
418			return runTUI(cmd, []judge.RunReport{single}, nil, resolveTheme(flags.theme), single.Run)
419		}
420		return fmt.Errorf("not_a_saved_board: %s is not a saved entire-judge report (expected `rank --json` or `run --json` output)", path)
421	}
