423	// resolveTheme picks the TUI theme from the --theme flag, falling back to the
424	// ENTIRE_JUDGE_THEME env var, then the default scheme.
425	func resolveTheme(flagValue string) tui.Theme {
426		name := flagValue
427		if name == "" {
428			name = os.Getenv("ENTIRE_JUDGE_THEME")
429		}
430		theme, _ := tui.ThemeByName(name)
431		return theme
432	}
